114	/*
115	 * @brief: 初始化 2K0300 SPI2-IO 控制器并配置引脚
116	 *         数据脚 GPIO64/65/66 复用为 spi2_clk/spi2_miso/spi2_mosi（主功能），
117	 *         片选 GPIO85 使用软件 GPIO 方式控制（bit-bang 实测片选）。
118	 */
119	static void LsHwSpiInit(void)
120	{
121	    volatile unsigned char *base = (volatile unsigned char *)LS_SPI2_BASE;
122	    uint32_t brint;
123	
124	    ls_pinmux_pin_setup(LOONG_HAT_SPI_CLK_GPIO, LS_PINMUX_MODE_AS_MAIN_FUNC);
125	    ls_pinmux_pin_setup(LOONG_HAT_SPI_MISO_GPIO, LS_PINMUX_MODE_AS_MAIN_FUNC);
126	    ls_pinmux_pin_setup(LOONG_HAT_SPI_MOSI_GPIO, LS_PINMUX_MODE_AS_MAIN_FUNC);
127	
128	    /* CS: GPIO 模式输出，默认高电平（未选中） */
129	    ls_pinmux_pin_setup(LOONG_HAT_SPI_CSN_GPIO, LS_PINMUX_MODE_AS_GPIO);
130	    IoTGpioInit(LOONG_HAT_SPI_CSN_GPIO);
131	    IoTGpioSetDir(LOONG_HAT_SPI_CSN_GPIO, IOT_GPIO_DIR_OUT);
132	    LsHwSpiCsSet(1);
133	
134	    /* 确保 SPI2/3 模块时钟门控打开（CHIP_CTRL05 0x16000114 bits[18:17]，缺省 0x3）。
135	     * 复位/U-Boot 配置可能将其关掉，若模块无时钟，传输永不完成，EOT 永不置位。 */
136	    {
137	        volatile unsigned int *cfg5 = (volatile unsigned int *)LS_GENERAL_CFG5;
138	        writel(readl(cfg5) | (0x3u << 17), cfg5);
139	    }
140	
141	    /* CFG3: 主模式、标准全双工（MISO 输入 / MOSI 输出）、软件片选模式 */
142	    writel(LS_SPI_CFG3_MSTR | LS_SPI_CFG3_DIE | LS_SPI_CFG3_DOE | LS_SPI_CFG3_SSMODE_SW,
143	           base + LS_SPI_IO_CFG3);
144	
145	    /* CFG1: SPI Mode 0（CPOL=0, CPHA=0），8bit 帧 */
146	    writel(LS_SPI_CFG1_DSIZE_8BIT, base + LS_SPI_IO_CFG1);
147	
148	    /* CFG2: 波特率分频 BRINT = APB时钟 / 目标SPI时钟 */
149	    brint = LOONG_HAT_SPI_APB_HZ / LOONG_HAT_SPI_CLK_HZ;
150	    if (brint < 2) {
151	        brint = 2;
152	    }
153	    if (brint > 255) {
154	        brint = 255;
155	    }
156	    writel((brint << LS_SPI_CFG2_BRINT_SHIFT) & LS_SPI_CFG2_BRINT_MASK,
157	           base + LS_SPI_IO_CFG2);
158	
159	    /* CR1: 使能 SPI（须在 CFGx 配置完成后写） */
160	    writel(LS_SPI_CR1_SPE, base + LS_SPI_IO_CR1);
161	}
