163	/*
164	 * @brief: 等待 SR1 中指定标志位置位
165	 * @param: flag: 期望置位的标志位
166	 * @param: clear: 非 0 时置位后写 1 清该标志
167	 * @return: 0 成功，-1 超时
168	 */
169	static int LsHwSpiWaitFlag(uint32_t flag, uint32_t clear)
170	{
171	    volatile unsigned char *sr1 = (volatile unsigned char *)(LS_SPI2_BASE + LS_SPI_IO_SR1);
172	    uint32_t val;
173	    uint32_t i;
174	
175	    for (i = 0; i < LS_SPI_WAIT_TIMEOUT_US; i++) {
176	        val = readl(sr1);
177	        if (val & flag) {
178	            if (clear) {
179	                writel(flag, sr1);
180	            }
181	            return 0;
182	        }
183	        LOS_UDelay(1);
184	    }
185	
186	    return -1;
187	}
