189	/*
190	 * @brief: 传输出错时立即释放片选并复位控制器传输状态。
191	 *         1. 挂起/停止控制器中可能仍在进行的传输（清 CSTART/AUTOSUS）；
192	 *         2. 把 CTSIZE(CR4) 清 0 强制本次传输立即结束，并把 TSIZE(CR3) 复位为 0，
193	 *            防止出错时残留的巨大 CTSIZE 被后续传输继承再次导致 EOT 永不置位；
194	 *         3. 清残留 W1C 状态标志；
195	 *         4. 排空 RXFIFO，避免残留数据干扰下一次读取；
196	 *         5. 立即把 CSN(GPIO85) 拉高释放 Flash，避免其卡在出错命令的指令态。
197	 */
198	static void LsHwSpiAbort(void)
199	{
200	    volatile unsigned char *base = (volatile unsigned char *)LS_SPI2_BASE;
201	    volatile unsigned char *sr1 = (volatile unsigned char *)(LS_SPI2_BASE + LS_SPI_IO_SR1);
202	    uint32_t val;
203	    uint32_t i;
204	
205	    /* 挂起/停止可能仍在进行的传输 */
206	    val = readl(base + LS_SPI_IO_CR1);
207	    val &= ~(LS_SPI_CR1_CSTART | LS_SPI_CR1_AUTOSUS);
208	    writel(val, base + LS_SPI_IO_CR1);
209	
210	    /* 强制本次传输立即结束（CTSIZE 写 0），并把单次帧数复位为 1（TSIZE=0） */
211	    writel(0, base + LS_SPI_IO_CR4);
212	    writel(0, base + LS_SPI_IO_CR3);
213	
214	    /* 等当前帧收尾、控制器回到空闲态（帧约 8us @1MHz） */
215	    LOS_UDelay(10);
216	
217	    /* 清残留状态标志位（W1C） */
218	    writel(LS_SPI_SR1_W1C_FLAGS, base + LS_SPI_IO_SR1);
219	
220	    /* 排空 RXFIFO（深度 4，防止残留数据导致下一次 RXA 立即命中读到旧数据） */
221	    for (i = 0; i < 4; i++) {
222	        if (readl(sr1) & LS_SPI_SR1_RXE) {
223	            break;
224	        }
225	        (void)readb(base + LS_SPI_IO_DR);
226	    }
227	
228	    /* 立即释放片选，CSN 恢复高电平（未选中） */
229	    LsHwSpiCsSet(1);
230	    LOS_UDelay(1);
231	}
