306	/*
307	 * @brief: 故意制造一次传输超时，触发 LsHwSpiAbort() 的 CSN 自动恢复路径。
308	 *         用大 TSIZE 启动传输使其远超 EOT 等待超时，等待超时后 abort() 会立即
309	 *         挂起控制器、清标志、排空 RXFIFO 并把 CSN(GPIO85) 拉高。
310	 *         用于验证出错释放片选后，控制器与 Flash 的读写时序仍正常。
311	 */
312	static void LsSpiFlashTriggerCsnAbort(void)
313	{
314	    volatile unsigned char *base = (volatile unsigned char *)LS_SPI2_BASE;
315	    uint32_t val;
316	
317	    printf(" LOONG_HAT SPI FLASH [test] inject transfer timeout, expect CSN auto-restore\r\n");
318	
319	    LsSpiFlashSelect();
320	    val = readl(base + LS_SPI_IO_CR1);
321	    val |= LS_SPI_CR1_SPE;
322	    writel(val, base + LS_SPI_IO_CR1);
323	    writel(LS_SPI_SR1_W1C_FLAGS, base + LS_SPI_IO_SR1);
324	
325	    /* TSIZE=0x4000 帧：@1MHz 约 131ms，远超 10ms 的 EOT 等待，保证必然超时 */
326	    writel(0x4000, base + LS_SPI_IO_CR3);
327	    writeb(0xFF, base + LS_SPI_IO_DR);
328	    val = readl(base + LS_SPI_IO_CR1);
329	    val |= LS_SPI_CR1_CSTART;
330	    writel(val, base + LS_SPI_IO_CR1);
331	
332	    if (LsHwSpiWaitFlag(LS_SPI_SR1_EOT, 1) != 0) {
333	        printf(" LOONG_HAT SPI FLASH [test] EOT timeout, abort() releases CSN\r\n");
334	        LsHwSpiAbort();
335	    } else {
336	        printf(" LOONG_HAT SPI FLASH [test] unexpected EOT set, force abort()\r\n");
337	        LsHwSpiAbort();
338	    }
339	}
