341	static void LsSpiFlashReadJedecId(uint8_t id[3])
342	{
343	    LsSpiFlashSelect();
344	    LsHwSpiXferByte(SPI_FLASH_CMD_READ_JEDEC_ID);
345	    id[0] = LsHwSpiXferByte(0xFF);
346	    id[1] = LsHwSpiXferByte(0xFF);
347	    id[2] = LsHwSpiXferByte(0xFF);
348	    LsSpiFlashDeselect();
349	}
