380	static int LsSpiFlashWaitReady(const char *op)
381	{
382	    uint8_t status = 0xFF;
383	
384	    for (uint32_t i = 0; i < 500; i++) {
385	        status = LsSpiFlashReadStatus();
386	        if ((status & SPI_FLASH_STATUS_WIP) == 0) {
387	            return 0;
388	        }
389	        LOS_Msleep(10);
390	    }
391	
392	    printf(" LOONG_HAT SPI FLASH %s timeout, status=0x%02x\r\n", op, status);
393	    return -1;
394	}
