396	static int LsSpiFlashSectorErase(uint32_t addr)
397	{
398	    LsSpiFlashWriteEnable();
399	
400	    LsSpiFlashSelect();
401	    LsHwSpiXferByte(SPI_FLASH_CMD_SECTOR_ERASE_4K);
402	    LsHwSpiXferByte((uint8_t)(addr >> 16));
403	    LsHwSpiXferByte((uint8_t)(addr >> 8));
404	    LsHwSpiXferByte((uint8_t)addr);
405	    LsSpiFlashDeselect();
406	
407	    return LsSpiFlashWaitReady("erase");
408	}
