453	static void SpiFlashTask(void)
454	{
455	    uint8_t id[3] = {0};
456	    uint8_t pattern[] = {
457	        'L', 'O', 'O', 'N', 'G', '-', 'H', 'A',
458	        'T', '-', 'S', 'P', 'I', '-', 'F', 'L', '\0'
459	    };
460	    uint8_t verify[sizeof(pattern)];
461	    uint32_t capacity;
462	    uint32_t sectorAddr;
463	    uint32_t testAddr;
464	    uint64_t t0;
465	    int ret;
466	
467	    printf("[Sample]: LOONG_HAT SPI FLASH hardware SPI2 demo start\r\n");
468	
469	    LsHwSpiInit();
470	    LOS_Msleep(20);
471	
472	    LsSpiFlashReadJedecId(id);
473	    printf(" LOONG_HAT SPI FLASH probe CSN GPIO%u JEDEC ID: %02x %02x %02x\r\n",
474	        LOONG_HAT_SPI_CSN_GPIO, id[0], id[1], id[2]);
475	
476	    if (!LsSpiFlashIdValid(id)) {
477	        while (1) {
478	            printf(" LOONG_HAT SPI FLASH not found: JEDEC ID invalid, check module/CS/pin mapping\r\n");
479	            LOS_Msleep(2000);
480	        }
481	    }
482	
483	    /* CSN 自动恢复自检：故意触发一次传输超时，验证 abort() 释放片选后，
484	     * 控制器与 Flash 的读写时序仍正常（后续 erase/program/verify 即为恢复后的验证） */
485	    LsSpiFlashTriggerCsnAbort();
486	
487	    (void)memset(id, 0, sizeof(id));
488	    LsSpiFlashReadJedecId(id);
489	    printf(" LOONG_HAT SPI FLASH [test] re-probe after CSN abort JEDEC ID: %02x %02x %02x\r\n",
490	        id[0], id[1], id[2]);
491	    if (!LsSpiFlashIdValid(id)) {
492	        printf(" LOONG_HAT SPI FLASH [test] FAIL: flash not responsive after CSN auto-restore\r\n");
493	        while (1) {
494	            LOS_Msleep(1000);
495	        }
496	    }
497	    printf(" LOONG_HAT SPI FLASH [test] PASS: CSN auto-restore, flash responsive\r\n");
498	
499	    capacity = LsSpiFlashCapacityBytes(id);
500	    if (capacity >= LOONG_HAT_SPI_SECTOR_SIZE * 2) {
501	        sectorAddr = capacity - LOONG_HAT_SPI_SECTOR_SIZE;
502	    } else {
503	        sectorAddr = 0;
504	    }
505	    testAddr = sectorAddr + LOONG_HAT_SPI_TEST_OFFSET;
506	
507	    printf(" LOONG_HAT SPI FLASH selected CS GPIO%u, status=0x%02x\r\n",
508	        LOONG_HAT_SPI_CSN_GPIO, LsSpiFlashReadStatus());
509	
510	    if (capacity != 0) {
511	        printf(" LOONG_HAT SPI FLASH capacity estimate: %u bytes\r\n", capacity);
512	    } else {
513	        printf(" LOONG_HAT SPI FLASH capacity unknown from ID, use sector 0 for test\r\n");
514	    }
515	
516	    printf(" LOONG_HAT SPI FLASH test: erase sector 0x%06x, write/read at 0x%06x\r\n",
517	        (unsigned int)sectorAddr, (unsigned int)testAddr);
518	
519	    t0 = LOS_TickCountGet();
520	    ret = LsSpiFlashSectorErase(sectorAddr);
521	    printf(" LOONG_HAT SPI FLASH erase ret=%d status=0x%02x (t=%llu ticks)\r\n",
522	        ret, LsSpiFlashReadStatus(), (unsigned long long)(LOS_TickCountGet() - t0));
523	    if (ret != 0) {
524	        while (1) {
525	            LOS_Msleep(1000);
526	        }
527	    }
528	
529	    t0 = LOS_TickCountGet();
530	    ret = LsSpiFlashPageProgram(testAddr, pattern, sizeof(pattern));
531	    printf(" LOONG_HAT SPI FLASH program:%s\r\n", pattern);
532	    printf(" LOONG_HAT SPI FLASH program ret=%d status=0x%02x (t=%llu ticks)\r\n",
533	        ret, LsSpiFlashReadStatus(), (unsigned long long)(LOS_TickCountGet() - t0));
534	    if (ret != 0) {
535	        while (1) {
536	            LOS_Msleep(1000);
537	        }
538	    }
539	
540	    (void)memset(verify, 0, sizeof(verify));
541	    LsSpiFlashReadData(testAddr, verify, sizeof(verify));
542	
543	    if (memcmp(pattern, verify, sizeof(pattern)) == 0) {
544	        printf(" LOONG_HAT SPI FLASH verify passed: ");
545	    } else {
546	        printf(" LOONG_HAT SPI FLASH verify failed: ");
547	    }
548	
549	    for (uint32_t i = 0; i < sizeof(verify); i++) {
550	        printf("%02x ", verify[i]);
551	    }
552	    printf("\r\n");
553	    printf(" LOONG_HAT SPI FLASH read:%s\r\n", verify);
554	
555	    /* 任务保持存活，不再周期打印 alive */
556	    while (1) {
557	        LOS_Msleep(2000);
558	    }
559	}
