562	{
563	    uint32_t ret;
564	    uint32_t taskId;
565	    TSK_INIT_PARAM_S task = {0};
566	
567	    printf("[Sample]: LOONG_HAT SPI FLASH entry\r\n");
568	
569	    task.pfnTaskEntry = (TSK_ENTRY_FUNC)SpiFlashTask;
570	    task.uwStackSize = SPI_FLASH_TASK_STACKSIZE;
