1	/****************************************************************************
2	 * apps/examples/ls_driver_test/test_eeprom.c
3	 *
4	 * EEPROM + BH1750 light sensor test for LS2K300 (LOONG-HAT).
5	 *
6	 * Function:
7	 *   1. On startup, read and print EEPROM contents
8	 *   2. When KEY1 (GPIO87) is pressed, read BH1750 light sensor 5 times,
9	 *      print each reading, then overwrite EEPROM with the new data
10	 *   3. When KEY2 (GPIO86) is pressed, exit the program
11	 *
12	 * Hardware (LOONG-HAT):
13	 *   - I2C1 SCL: GPIO50, SDA: GPIO51
14	 *   - EEPROM addr: 0x50 (AT24C02)
15	 *   - BH1750 addr: 0x23 (or 0x5C)
16	 *   - KEY1: GPIO87, KEY2: GPIO86
17	 *
18	 ****************************************************************************/
19	
20	/****************************************************************************
21	 * Included Files
22	 ****************************************************************************/
23	
24	#include <nuttx/config.h>
25	
26	#include <sys/ioctl.h>
27	#include <stdio.h>
28	#include <string.h>
29	#include <fcntl.h>
30	#include <errno.h>
31	#include <unistd.h>
32	#include <stdint.h>
33	
34	#include <nuttx/i2c/i2c_master.h>
35	#include <nuttx/ioexpander/gpio.h>
36	#include <nuttx/arch.h>
37	
38	#include "ls_driver_test.h"
39	
40	/****************************************************************************
41	 * Pre-processor Definitions
42	 ****************************************************************************/
43	
44	#define I2C1_PATH           "/dev/i2c1"
45	#define I2C_FREQ            I2C_SPEED_STANDARD
46	
47	/* EEPROM (AT24C02) definitions */
48	
49	#define EEPROM_ADDR         0x50
50	#define EEPROM_SIZE         256
51	#define EEPROM_PAGE_SIZE    8
52	#define EEPROM_WRITE_DELAY  20
53	
54	/* EEPROM memory layout:
55	 *   0x0000        - magic (0xA5 = valid data)
56	 *   0x0001        - number of stored readings (uint8_t)
57	 *   0x0010..0x0019 - 5 x uint16_t light readings (lux * 100)
58	 */
59	
60	#define EEPROM_MAGIC_ADDR   0x0000
61	#define EEPROM_COUNT_ADDR   0x0001
62	#define EEPROM_DATA_ADDR    0x0010
63	#define EEPROM_MAGIC_VALUE  0xA5
64	#define EEPROM_MAX_READINGS 5
65	
66	/* BH1750 definitions */
67	
68	#define BH1750_ADDR_LOW     0x23
69	#define BH1750_ADDR_HIGH    0x5c
70	#define BH1750_POWER_ON     0x01
71	#define BH1750_RESET        0x07
72	#define BH1750_H_MODE       0x10
73	
74	/* GPIO definitions */
75	
76	#define KEY1_GPIO           87
77	#define KEY2_GPIO           86
78	
79	/* Timing */
80	
81	#define KEY_SCAN_DELAY_MS   10
82	#define KEY_DEBOUNCE_MS     20
83	#define BH1750_READ_DELAY   180
84	
85	/****************************************************************************
86	 * Private Data
87	 ****************************************************************************/
88	
89	static int g_i2c_fd = -1;
90	static uint8_t g_bh1750_addr = BH1750_ADDR_LOW;
91	
92	/****************************************************************************
93	 * Private Functions - I2C Helper
94	 ****************************************************************************/
95	
96	static int eeprom_i2c_write(uint8_t addr, const uint8_t *data, int len)
97	{
98	  struct i2c_msg_s msg;
99	  struct i2c_transfer_s trans;
100	
101	  msg.frequency = I2C_FREQ;
102	  msg.addr      = addr;
103	  msg.flags     = 0;
104	  msg.buffer    = (FAR uint8_t *)data;
105	  msg.length    = len;
106	
107	  trans.msgv = &msg;
108	  trans.msgc = 1;
109	
110	  return ioctl(g_i2c_fd, I2CIOC_TRANSFER, (unsigned long)&trans);
111	}
112	
113	static int eeprom_i2c_read(uint8_t addr, uint8_t *data, int len)
114	{
115	  struct i2c_msg_s msg;
116	  struct i2c_transfer_s trans;
117	
118	  msg.frequency = I2C_FREQ;
119	  msg.addr      = addr;
120	  msg.flags     = I2C_M_READ;
121	  msg.buffer    = data;
122	  msg.length    = len;
123	
124	  trans.msgv = &msg;
125	  trans.msgc = 1;
126	
127	  return ioctl(g_i2c_fd, I2CIOC_TRANSFER, (unsigned long)&trans);
128	}
129	
130	/****************************************************************************
131	 * Private Functions - EEPROM
132	 ****************************************************************************/
133	
134	static int eeprom_read_byte(uint16_t mem_addr, uint8_t *data)
135	{
136	  uint8_t addr[2];
137	  int ret;
138	
139	  addr[0] = (uint8_t)(mem_addr >> 8);
140	  addr[1] = (uint8_t)(mem_addr & 0xff);
141	
142	  ret = eeprom_i2c_write(EEPROM_ADDR, addr, 2);
143	  if (ret < 0)
144	    {
145	      return ret;
146	    }
147	
148	  return eeprom_i2c_read(EEPROM_ADDR, data, 1);
149	}
150	
151	static int eeprom_write_byte(uint16_t mem_addr, uint8_t data)
152	{
153	  uint8_t buf[3];
154	
155	  buf[0] = (uint8_t)(mem_addr >> 8);
156	  buf[1] = (uint8_t)(mem_addr & 0xff);
157	  buf[2] = data;
158	
159	  return eeprom_i2c_write(EEPROM_ADDR, buf, 3);
160	}
161	
162	static int eeprom_write_page(uint16_t mem_addr,
163	                             const uint8_t *data, int len)
164	{
165	  uint8_t buf[2 + EEPROM_PAGE_SIZE];
166	  int i;
167	
168	  if (len > EEPROM_PAGE_SIZE)
169	    {
170	      len = EEPROM_PAGE_SIZE;
171	    }
172	
173	  buf[0] = (uint8_t)(mem_addr >> 8);
174	  buf[1] = (uint8_t)(mem_addr & 0xff);
175	  for (i = 0; i < len; i++)
176	    {
177	      buf[2 + i] = data[i];
178	    }
179	
180	  return eeprom_i2c_write(EEPROM_ADDR, buf, 2 + len);
181	}
182	
183	static int eeprom_read_bytes(uint16_t mem_addr,
184	                             uint8_t *data, int len)
185	{
186	  uint8_t addr[2];
187	  int ret;
188	
189	  addr[0] = (uint8_t)(mem_addr >> 8);
190	  addr[1] = (uint8_t)(mem_addr & 0xff);
191	
192	  ret = eeprom_i2c_write(EEPROM_ADDR, addr, 2);
193	  if (ret < 0)
194	    {
195	      return ret;
196	    }
197	
198	  return eeprom_i2c_read(EEPROM_ADDR, data, len);
199	}
200	
201	static void eeprom_print_contents(void)
202	{
203	  uint8_t magic;
204	  uint8_t count;
205	  uint8_t i;
206	  int ret;
207	
208	  printf("[EEPROM] ---- Current EEPROM Contents ----\n");
209	
210	  ret = eeprom_read_byte(EEPROM_MAGIC_ADDR, &magic);
211	  if (ret < 0)
212	    {
213	      printf("[EEPROM] ERROR: read magic failed: %d\n", ret);
214	      return;
215	    }
216	
217	  printf("[EEPROM] Magic: 0x%02X (%s)\n",
218	         magic, (magic == EEPROM_MAGIC_VALUE) ? "valid" : "invalid");
219	
220	  if (magic != EEPROM_MAGIC_VALUE)
221	    {
222	      printf("[EEPROM] No valid data stored\n");
223	      printf("[EEPROM] ---- End of EEPROM ----\n\n");
224	      return;
225	    }
226	
227	  ret = eeprom_read_byte(EEPROM_COUNT_ADDR, &count);
228	  if (ret < 0)
229	    {
230	      printf("[EEPROM] ERROR: read count failed: %d\n", ret);
231	      return;
232	    }
233	
234	  printf("[EEPROM] Stored readings: %u\n", count);
235	
236	  if (count > EEPROM_MAX_READINGS)
237	    {
238	      count = EEPROM_MAX_READINGS;
239	    }
240	
241	  for (i = 0; i < count; i++)
242	    {
243	      uint8_t buf[2];
244	      uint16_t lux_x100;
245	
246	      ret = eeprom_read_bytes(EEPROM_DATA_ADDR + i * 2, buf, 2);
247	      if (ret < 0)
248	        {
249	          printf("[EEPROM]   [%u] read error: %d\n", i, ret);
250	          continue;
251	        }
252	
253	      lux_x100 = ((uint16_t)buf[0] << 8) | buf[1];
254	      printf("[EEPROM]   [%u] %u.%02u lux\n",
255	             i, lux_x100 / 100, lux_x100 % 100);
256	    }
257	
258	  printf("[EEPROM] ---- End of EEPROM ----\n\n");
259	}
260	
261	static int eeprom_save_readings(const uint16_t *readings, int count)
262	{
263	  uint8_t buf[EEPROM_MAX_READINGS * 2];
264	  int i;
265	  int ret;
266	  int page_off;
267	  int page_len;
268	
269	  if (count > EEPROM_MAX_READINGS)
270	    {
271	      count = EEPROM_MAX_READINGS;
272	    }
273	
274	  /* Pack readings into byte array (big-endian uint16_t) */
275	
276	  for (i = 0; i < count; i++)
277	    {
278	      buf[i * 2]     = (uint8_t)(readings[i] >> 8);
279	      buf[i * 2 + 1] = (uint8_t)(readings[i] & 0xff);
280	    }
281	
282	  /* Write count */
283	
284	  ret = eeprom_write_byte(EEPROM_COUNT_ADDR, (uint8_t)count);
285	  if (ret < 0)
286	    {
287	      printf("[EEPROM] ERROR: write count failed: %d\n", ret);
288	      return ret;
289	    }
290	
291	  usleep(EEPROM_WRITE_DELAY * 1000);
292	
293	  /* Write data in page-sized chunks */
294	
295	  for (page_off = 0; page_off < count * 2; page_off += EEPROM_PAGE_SIZE)
296	    {
297	      page_len = count * 2 - page_off;
298	      if (page_len > EEPROM_PAGE_SIZE)
299	        {
300	          page_len = EEPROM_PAGE_SIZE;
301	        }
302	
303	      ret = eeprom_write_page(EEPROM_DATA_ADDR + page_off,
304	                              &buf[page_off], page_len);
305	      if (ret < 0)
306	        {
307	          printf("[EEPROM] ERROR: write data at 0x%04X failed: %d\n",
308	                 EEPROM_DATA_ADDR + page_off, ret);
309	          return ret;
310	        }
311	
312	      usleep(EEPROM_WRITE_DELAY * 1000);
313	    }
314	
315	  /* Write magic last (signals data is valid) */
316	
317	  ret = eeprom_write_byte(EEPROM_MAGIC_ADDR, EEPROM_MAGIC_VALUE);
318	  if (ret < 0)
319	    {
320	      printf("[EEPROM] ERROR: write magic failed: %d\n", ret);
321	      return ret;
322	    }
323	
324	  usleep(EEPROM_WRITE_DELAY * 1000);
325	
326	  /* Verify */
327	
328	  for (i = 0; i < count; i++)
329	    {
330	      uint8_t verify[2];
331	      uint16_t stored;
332	
333	      ret = eeprom_read_bytes(EEPROM_DATA_ADDR + i * 2, verify, 2);
334	      if (ret < 0)
335	        {
336	          printf("[EEPROM] ERROR: verify read [%d] failed: %d\n", i, ret);
337	          return ret;
338	        }
339	
340	      stored = ((uint16_t)verify[0] << 8) | verify[1];
341	      if (stored != readings[i])
342	        {
343	          printf("[EEPROM] ERROR: verify mismatch [%d]: "
344	                 "expected %u, got %u\n", i, readings[i], stored);
345	          return -EIO;
346	        }
347	    }
348	
349	  printf("[EEPROM] Saved and verified %d readings\n", count);
350	  return OK;
351	}
