356	
357	static int bh1750_write_cmd(uint8_t cmd)
358	{
359	  return eeprom_i2c_write(g_bh1750_addr, &cmd, 1);
360	}
361	
362	static int bh1750_init(void)
363	{
364	  int ret;
365	
366	  g_bh1750_addr = BH1750_ADDR_LOW;
367	  ret = bh1750_write_cmd(BH1750_POWER_ON);
368	  if (ret < 0)
369	    {
370	      printf("[BH1750] probe addr 0x%02x failed\n", BH1750_ADDR_LOW);
371	      g_bh1750_addr = BH1750_ADDR_HIGH;
372	      ret = bh1750_write_cmd(BH1750_POWER_ON);
373	    }
374	
375	  if (ret < 0)
376	    {
377	      printf("[BH1750] probe addr 0x%02x failed\n", BH1750_ADDR_HIGH);
378	      printf("[BH1750] no ACK, check wiring\n");
379	      return ret;
380	    }
381	
382	  printf("[BH1750] detected addr=0x%02x\n", g_bh1750_addr);
383	  usleep(20000);
384	
385	  ret = bh1750_write_cmd(BH1750_RESET);
386	  if (ret < 0)
387	    {
388	      printf("[BH1750] reset failed\n");
389	      return ret;
390	    }
391	
392	  usleep(20000);
393	
394	  ret = bh1750_write_cmd(BH1750_H_MODE);
395	  if (ret < 0)
396	    {
397	      printf("[BH1750] set H-mode failed\n");
398	      return ret;
399	    }
400	
401	  usleep(BH1750_READ_DELAY * 1000);
402	
403	  printf("[BH1750] init OK\n");
404	  return OK;
405	}
