407	static int bh1750_read_lux(uint16_t *lux_x100)
408	{
409	  uint8_t buf[2] = {0};
410	  int ret;
411	  uint16_t raw;
412	
413	  ret = eeprom_i2c_read(g_bh1750_addr, buf, 2);
414	  if (ret < 0)
415	    {
416	      printf("[BH1750] read failed: %d\n", ret);
417	      return ret;
418	    }
419	
420	  raw = ((uint16_t)buf[0] << 8) | buf[1];
421	  *lux_x100 = (uint16_t)((raw * 1000 + 6) / 12);
422	
423	  return OK;
424	}
