443	  snprintf(path, sizeof(path), "/dev/gpio%d", gpio);
444	  fd = open(path, O_RDWR);
445	  if (fd < 0)
446	    {
447	      printf("[EEPROM] ERROR: open %s failed: %d\n", path, errno);
448	      return -errno;
449	    }
