471	static int is_key_pressed(int fd, bool *last)
472	{
473	  bool value = get_key_value(fd);
474	
475	  if (!value && *last)
476	    {
477	      up_mdelay(KEY_DEBOUNCE_MS);
478	      value = get_key_value(fd);
479	      if (!value)
480	        {
481	          *last = value;
482	          return 1;
483	        }
484	    }
