491	 * Private Functions - Light Sensor Read and Save
492	 ****************************************************************************/
493	
494	static int read_and_save_light(void)
495	{
496	  uint16_t readings[EEPROM_MAX_READINGS];
497	  int bh1750_ok = 0;
498	  int i;
499	  int ret;
500	
501	  printf("\n[EEPROM] === KEY1 pressed: reading light sensor 5 times ===\n");
502	
503	  /* Initialize BH1750 */
504	
505	  ret = bh1750_init();
506	  if (ret < 0)
507	    {
508	      printf("[EEPROM] BH1750 init failed, aborting\n");
509	      return ret;
510	    }
511	
512	  bh1750_ok = 1;
513	
514	  /* Read 5 times */
515	
516	  for (i = 0; i < EEPROM_MAX_READINGS; i++)
517	    {
518	      usleep(300000);  /* 300ms between readings */
519	
520	      if (bh1750_ok)
521	        {
522	          ret = bh1750_read_lux(&readings[i]);
523	          if (ret < 0)
524	            {
525	              printf("[EEPROM]   [%d] BH1750 read failed: %d\n", i, ret);
526	              readings[i] = 0;
527	              /* Try reinit */
528	
529	              usleep(500000);
530	              bh1750_ok = (bh1750_init() == 0);
531	            }
532	          else
533	            {
534	              printf("[EEPROM]   [%d] light = %u.%02u lux\n",
535	                     i, readings[i] / 100, readings[i] % 100);
536	            }
537	        }
538	      else
539	        {
540	          readings[i] = 0;
541	          printf("[EEPROM]   [%d] sensor unavailable\n", i);
542	        }
543	    }
544	
545	  /* Save to EEPROM */
546	
547	  printf("[EEPROM] Saving readings to EEPROM...\n");
548	  ret = eeprom_save_readings(readings, EEPROM_MAX_READINGS);
549	  if (ret < 0)
550	    {
551	      printf("[EEPROM] Save failed!\n");
552	      return ret;
553	    }
554	
555	  /* Print updated EEPROM contents */
556	
557	  printf("[EEPROM] Verifying EEPROM contents:\n");
558	  eeprom_print_contents();
559	
560	  return OK;
561	}
