566	
567	int test_eeprom(void)
568	{
569	  int fd_key1;
570	  int fd_key2;
571	  bool key1_last;
572	  bool key2_last;
573	  int ret;
574	
575	  printf("[EEPROM] === EEPROM + BH1750 Light Sensor Test ===\n");
576	  printf("[EEPROM] I2C1: SCL=GPIO50 SDA=GPIO51\n");
577	  printf("[EEPROM] EEPROM addr=0x%02X, BH1750 addr=0x%02X/0x%02X\n",
578	         EEPROM_ADDR, BH1750_ADDR_LOW, BH1750_ADDR_HIGH);
579	  printf("[EEPROM] KEY1=GPIO%d: read light x5, overwrite EEPROM\n",
580	         KEY1_GPIO);
581	  printf("[EEPROM] KEY2=GPIO%d: exit program\n\n", KEY2_GPIO);
582	
583	  /* Open I2C1 */
584	
585	  printf("[EEPROM] Opening %s...\n", I2C1_PATH);
586	  g_i2c_fd = open(I2C1_PATH, O_RDWR);
587	  if (g_i2c_fd < 0)
588	    {
589	      printf("[EEPROM] ERROR: open %s failed: errno=%d\n",
590	             I2C1_PATH, errno);
591	      return -errno;
592	    }
593	
594	  printf("[EEPROM] I2C1 opened, fd=%d\n\n", g_i2c_fd);
595	
596	  /* Read and print current EEPROM contents */
597	
598	  printf("[EEPROM] Reading current EEPROM contents...\n");
599	  eeprom_print_contents();
600	
601	  /* Initialize KEY1 */
602	
603	  fd_key1 = init_key_gpio(KEY1_GPIO);
604	  if (fd_key1 < 0)
605	    {
606	      close(g_i2c_fd);
607	      return fd_key1;
608	    }
609	
610	  /* Initialize KEY2 */
611	
612	  fd_key2 = init_key_gpio(KEY2_GPIO);
613	  if (fd_key2 < 0)
614	    {
615	      close(fd_key1);
616	      close(g_i2c_fd);
617	      return fd_key2;
618	    }
619	
620	  key1_last = get_key_value(fd_key1);
621	  key2_last = get_key_value(fd_key2);
622	  printf("[EEPROM] KEY1(GPIO%d) ready, waiting for press...\n",
623	         KEY1_GPIO);
624	  printf("[EEPROM] KEY2(GPIO%d) ready, press to exit\n\n",
625	         KEY2_GPIO);
626	
627	  /* Main loop - wait for KEY1 press, KEY2 to exit */
628	
629	  while (1)
630	    {
631	      if (is_key_pressed(fd_key1, &key1_last))
632	        {
633	          ret = read_and_save_light();
634	          if (ret < 0)
635	            {
636	              printf("[EEPROM] read_and_save_light failed: %d\n", ret);
637	            }
638	
639	          printf("\n[EEPROM] Waiting for next KEY1 press...\n\n");
640	        }
641	
642	      if (is_key_pressed(fd_key2, &key2_last))
643	        {
644	          printf("\n[EEPROM] KEY2 pressed, exiting...\n");
645	          break;
646	        }
647	
648	      up_mdelay(KEY_SCAN_DELAY_MS);
649	    }
650	
651	  /* Cleanup */
652	
653	  close(fd_key2);
654	  close(fd_key1);
655	  close(g_i2c_fd);
656	  g_i2c_fd = -1;
657	
658	  printf("[EEPROM] Test complete.\n");
659	  return OK;
660	}
