86	static uint32_t ls2k300_spiio_setfrequency(FAR struct spi_dev_s *dev,
87	                                           uint32_t frequency)
88	{
89	  FAR struct ls2k300_spiio_priv_s *priv =
90	      (FAR struct ls2k300_spiio_priv_s *)dev;
91	  uint32_t cfg2;
92	  uint32_t brint;
93	  uint32_t brdec;
94	  uint32_t div;
95	
96	  if (frequency == 0)
97	    {
98	      frequency = priv->clock_freq / 2;
99	    }
100	
101	  div = priv->clock_freq / (2 * frequency);
102	  if (div < 1)
103	    {
104	      div = 1;
105	    }
106	
107	  brint = div / 2;
108	  if (brint < 1)
109	    {
110	      brint = 1;
111	    }
112	  if (brint > 255)
113	    {
114	      brint = 255;
115	    }
116	
117	  brdec = div - brint * 2;
118	  if (brdec > 3)
119	    {
120	      brdec = 3;
121	    }
122	
123	  cfg2 = spiio_read_reg(priv, LS2K300_SPIIO_CFG2);
124	  cfg2 &= ~(CFG2_BRINT_MASK | CFG2_BRDEC_MASK);
125	  cfg2 |= (brint << CFG2_BRINT_SHIFT) | brdec;
126	  spiio_write_reg(priv, LS2K300_SPIIO_CFG2, cfg2);
127	
128	  priv->frequency = priv->clock_freq / (2 * div);
129	  return priv->frequency;
130	}
