182	static uint32_t ls2k300_spiio_send(FAR struct spi_dev_s *dev, uint32_t wd)
183	{
184	  FAR struct ls2k300_spiio_priv_s *priv =
185	      (FAR struct ls2k300_spiio_priv_s *)dev;
186	
187	  if (spiio_idle_sr1(priv, SR1_TXA, SPIIO_TIMEOUT) < 0)
188	    {
189	      return 0;
190	    }
191	
192	  spiio_write_reg_byte(priv, LS2K300_SPIIO_DR, (uint8_t)(wd & 0xff));
193	
194	  spiio_write_reg(priv, LS2K300_SPIIO_CR1,
195	                  CR1_SPE | CR1_CSTART | CR1_AUTOSUS);
196	
197	  if (spiio_idle_sr1(priv, SR1_EOT, SPIIO_TIMEOUT) < 0)
198	    {
199	      return 0;
200	    }
201	
202	  spiio_write_reg(priv, LS2K300_SPIIO_SR1, SR1_EOT);
203	
204	  if (spiio_idle_sr1(priv, SR1_RXA, SPIIO_TIMEOUT) < 0)
205	    {
206	      return 0;
207	    }
208	
209	  return (uint32_t)spiio_read_reg_byte(priv, LS2K300_SPIIO_DR);
210	}
