333	    {
334	      cfg1 = spiio_read_reg(priv, LS2K300_SPIIO_CFG1);
335	      cfg1 &= ~CFG1_DSIZE_MASK;
336	      cfg1 |= ((8 - 1) << CFG1_DSIZE_SHIFT);
337	      spiio_write_reg(priv, LS2K300_SPIIO_CFG1, cfg1);
338	
339	      cfg3 = spiio_read_reg(priv, LS2K300_SPIIO_CFG3);
340	      cfg3 |= CFG3_MSTR;
341	      cfg3 |= CFG3_DIOSWP;
342	      cfg3 |= CFG3_DIE;
343	      cfg3 |= CFG3_DOE;
344	      cfg3 &= ~CFG3_SSMODE_MASK;
345	      cfg3 |= 0x200;
346	      spiio_write_reg(priv, LS2K300_SPIIO_CFG3, cfg3);
347	
348	      spiio_write_reg(priv, LS2K300_SPIIO_IER, 0);
349	
350	      priv->initialized = true;
351	    }
352	
353	  return &priv->dev;
