90	void ls2k300_hardware_init()
91	{
92	  /* GPIO50/51 配置为 I2C1 功能 (MAIN_FUNC = 0x3) */
93	  ls_pinmux_pin_setup(50, LS_PINMUX_MODE_AS_MAIN_FUNC);
94	  ls_pinmux_pin_setup(51, LS_PINMUX_MODE_AS_MAIN_FUNC);
95	
96	  /* SPI0 引脚复用配置
97	   * GPIO64 (SPI0_CLK)  -> MAIN_FUNC (0x3)
98	   * GPIO65 (SPI0_MISO) -> MAIN_FUNC (0x3)
99	   * GPIO66 (SPI0_MOSI) -> MAIN_FUNC (0x3)
100	   * GPIO67 (SPI0_CSN1) -> GPIO (0x0), 用于 MCP3204 软件片选
101	   */
102	  ls_pinmux_pin_setup(64, LS_PINMUX_MODE_AS_MAIN_FUNC);
103	  ls_pinmux_pin_setup(65, LS_PINMUX_MODE_AS_MAIN_FUNC);
104	  ls_pinmux_pin_setup(66, LS_PINMUX_MODE_AS_MAIN_FUNC);
105	  ls_pinmux_pin_setup(67, LS_PINMUX_MODE_AS_GPIO);
106	
107	  /* PWM2 引脚复用：GPIO88 -> SECOND_FUNC (0x2)，硬件 PWM 输出 */
108	  ls_pinmux_pin_setup(88, LS_PINMUX_MODE_AS_SECOND_FUNC);
109	}
