/****************************************************************************
 * apps/examples/ls_driver_test/test_spiflash.c
 *
 * SPI Flash test for LS2K300 (LOONG-HAT).
 *
 * Function:
 *   1. Initialize SPI2 IO controller and GPIO85 as software chip select
 *   2. Read JEDEC ID to detect SPI Flash
 *   3. Erase last 4KB sector, write test pattern, read back and verify
 *
 * Hardware (LOONG-HAT 40PIN header):
 *   - SCK  : GPIO64 / J12 Pin23 -> spi2_clk  (MAIN_FUNC)
 *   - MISO : GPIO65 / J12 Pin21 -> spi2_miso (MAIN_FUNC)
 *   - MOSI : GPIO66 / J12 Pin19 -> spi2_mosi (MAIN_FUNC)
 *   - CSN  : GPIO85 / J12 Pin26 -> GPIO software CS
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <sys/ioctl.h>
#include <stdio.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <stdint.h>

#include <nuttx/spi/spi.h>
#include <nuttx/ioexpander/gpio.h>
#include <nuttx/arch.h>

#include "ls_driver_test.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* SPI Flash commands (standard W25/Winbond compatible) */

#define SPIFLASH_CMD_WRITE_ENABLE     0x06
#define SPIFLASH_CMD_READ_STATUS      0x05
#define SPIFLASH_CMD_READ_JEDEC_ID    0x9f
#define SPIFLASH_CMD_READ_DATA        0x03
#define SPIFLASH_CMD_PAGE_PROGRAM     0x02
#define SPIFLASH_CMD_SECTOR_ERASE_4K  0x20

/* SPI Flash status register bits */

#define SPIFLASH_STATUS_WIP           0x01

/* SPI configuration */

#define SPIFLASH_SPI_PORT             0       /* SPIIO2 = port 0 */
#define SPIFLASH_CS_GPIO              85      /* GPIO85, software CS */
#define SPIFLASH_SPI_FREQ             1000000 /* 1 MHz */
#define SPIFLASH_SPI_MODE             SPIDEV_MODE0
#define SPIFLASH_SPI_BITS             8

/* Test parameters */

#define SPIFLASH_SECTOR_SIZE          4096U
#define SPIFLASH_TEST_OFFSET          0x100U
#define SPIFLASH_WAIT_TIMEOUT_MS      5000
#define SPIFLASH_ERASE_WAIT_MS        500

/****************************************************************************
 * Private Data
 ****************************************************************************/

static FAR struct spi_dev_s *g_spi_dev = NULL;

/****************************************************************************
 * Private Functions - GPIO (Chip Select)
 ****************************************************************************/

static int spiflash_cs_init(void)
{
  int ret;
  char path[32];
  int fd;

  /* Set GPIO85 to GPIO function */

  ret = pinctrl_set_gpio_function(SPIFLASH_CS_GPIO);
  if (ret < 0)
    {
      printf("[SPIFLASH] ERROR: pinctrl failed for GPIO%d\n",
             SPIFLASH_CS_GPIO);
      return ret;
    }

  /* Open GPIO device */

  snprintf(path, sizeof(path), "/dev/gpio%d", SPIFLASH_CS_GPIO);
  fd = open(path, O_RDWR);
  if (fd < 0)
    {
      printf("[SPIFLASH] ERROR: open %s failed: %d\n", path, errno);
      return -errno;
    }

  /* Configure as output */

  ret = ioctl(fd, GPIOC_SETPINTYPE, (unsigned long)GPIO_OUTPUT_PIN);
  if (ret < 0)
    {
      printf("[SPIFLASH] ERROR: GPIOC_SETPINTYPE(OUTPUT) on GPIO%d: %d\n",
             SPIFLASH_CS_GPIO, errno);
      close(fd);
      return -errno;
    }

  /* Default high (deselected) */

  ret = ioctl(fd, GPIOC_WRITE, (unsigned long)true);
  if (ret < 0)
    {
      printf("[SPIFLASH] ERROR: GPIOC_WRITE on GPIO%d: %d\n",
             SPIFLASH_CS_GPIO, errno);
      close(fd);
      return -errno;
    }

  close(fd);
  return OK;
}

static void spiflash_cs_select(void)
{
  char path[32];
  int fd;

  snprintf(path, sizeof(path), "/dev/gpio%d", SPIFLASH_CS_GPIO);
  fd = open(path, O_RDWR);
  if (fd >= 0)
    {
      ioctl(fd, GPIOC_WRITE, (unsigned long)false);  /* Active low */
      close(fd);
    }

  usleep(1);
}

static void spiflash_cs_deselect(void)
{
  char path[32];
  int fd;

  snprintf(path, sizeof(path), "/dev/gpio%d", SPIFLASH_CS_GPIO);
  fd = open(path, O_RDWR);
  if (fd >= 0)
    {
      ioctl(fd, GPIOC_WRITE, (unsigned long)true);  /* High = deselected */
      close(fd);
    }

  usleep(1);
}

/****************************************************************************
 * Private Functions - SPI Transfer
 ****************************************************************************/

static uint8_t spiflash_xfer_byte(uint8_t tx)
{
  uint32_t rx;

  rx = SPI_EXCHANGE(g_spi_dev, &tx, NULL, 1);
  return (uint8_t)(rx & 0xff);
}

/****************************************************************************
 * Private Functions - SPI Flash Operations
 ****************************************************************************/

static void spiflash_read_jedec_id(uint8_t id[3])
{
  spiflash_cs_select();
  spiflash_xfer_byte(SPIFLASH_CMD_READ_JEDEC_ID);
  id[0] = spiflash_xfer_byte(0xff);
  id[1] = spiflash_xfer_byte(0xff);
  id[2] = spiflash_xfer_byte(0xff);
  spiflash_cs_deselect();
}

static int spiflash_id_valid(const uint8_t id[3])
{
  if ((id[0] == 0x00 && id[1] == 0x00 && id[2] == 0x00) ||
      (id[0] == 0xff && id[1] == 0xff && id[2] == 0xff))
    {
      return 0;
    }

  return 1;
}

static uint8_t spiflash_read_status(void)
{
  uint8_t status;

  spiflash_cs_select();
  spiflash_xfer_byte(SPIFLASH_CMD_READ_STATUS);
  status = spiflash_xfer_byte(0xff);
  spiflash_cs_deselect();

  return status;
}

static void spiflash_write_enable(void)
{
  spiflash_cs_select();
  spiflash_xfer_byte(SPIFLASH_CMD_WRITE_ENABLE);
  spiflash_cs_deselect();
}

static int spiflash_wait_ready(FAR const char *op)
{
  uint8_t status = 0xff;
  int i;

  for (i = 0; i < SPIFLASH_WAIT_TIMEOUT_MS / 10; i++)
    {
      status = spiflash_read_status();
      if ((status & SPIFLASH_STATUS_WIP) == 0)
        {
          return OK;
        }

      usleep(10000);  /* 10ms */
    }

  printf("[SPIFLASH] %s timeout, status=0x%02x\n", op, status);
  return -ETIMEDOUT;
}

static int spiflash_sector_erase(uint32_t addr)
{
  spiflash_write_enable();

  spiflash_cs_select();
  spiflash_xfer_byte(SPIFLASH_CMD_SECTOR_ERASE_4K);
  spiflash_xfer_byte((uint8_t)(addr >> 16));
  spiflash_xfer_byte((uint8_t)(addr >> 8));
  spiflash_xfer_byte((uint8_t)addr);
  spiflash_cs_deselect();

  return spiflash_wait_ready("erase");
}

static int spiflash_page_program(uint32_t addr, FAR const uint8_t *data,
                                 uint32_t len)
{
  uint32_t i;

  spiflash_write_enable();

  spiflash_cs_select();
  spiflash_xfer_byte(SPIFLASH_CMD_PAGE_PROGRAM);
  spiflash_xfer_byte((uint8_t)(addr >> 16));
  spiflash_xfer_byte((uint8_t)(addr >> 8));
  spiflash_xfer_byte((uint8_t)addr);

  for (i = 0; i < len; i++)
    {
      spiflash_xfer_byte(data[i]);
    }

  spiflash_cs_deselect();

  return spiflash_wait_ready("program");
}

static void spiflash_read_data(uint32_t addr, FAR uint8_t *data,
                               uint32_t len)
{
  uint32_t i;

  spiflash_cs_select();
  spiflash_xfer_byte(SPIFLASH_CMD_READ_DATA);
  spiflash_xfer_byte((uint8_t)(addr >> 16));
  spiflash_xfer_byte((uint8_t)(addr >> 8));
  spiflash_xfer_byte((uint8_t)addr);

  for (i = 0; i < len; i++)
    {
      data[i] = spiflash_xfer_byte(0xff);
    }

  spiflash_cs_deselect();
}

static uint32_t spiflash_capacity_bytes(const uint8_t id[3])
{
  if (id[2] < 16 || id[2] > 30)
    {
      return 0;
    }

  return (uint32_t)(1UL << id[2]);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int test_spiflash(void)
{
  uint8_t id[3] = {0};
  uint8_t pattern[] = {
    'L', 'O', 'O', 'N', 'G', '-', 'H', 'A',
    'T', '-', 'S', 'P', 'I', '-', 'F', 'L', '\0'
  };
  uint8_t verify[sizeof(pattern)];
  uint32_t capacity;
  uint32_t sector_addr;
  uint32_t test_addr;
  int ret;
  int i;

  printf("[SPIFLASH] === SPI Flash Test (SPIIO2 + GPIO%d CS) ===\n",
         SPIFLASH_CS_GPIO);
  printf("[SPIFLASH] SCK=GPIO64 MISO=GPIO65 MOSI=GPIO66 CSN=GPIO%d\n",
         SPIFLASH_CS_GPIO);

  /* Initialize chip select GPIO */

  ret = spiflash_cs_init();
  if (ret < 0)
    {
      printf("[SPIFLASH] ERROR: CS init failed: %d\n", ret);
      return ret;
    }

  printf("[SPIFLASH] CS GPIO%d initialized (default high)\n",
         SPIFLASH_CS_GPIO);

  /* Initialize SPI IO controller */

  printf("[SPIFLASH] Initializing SPIIO2...\n");
  g_spi_dev = ls2k300_spiio_initialize(SPIFLASH_SPI_PORT);
  if (g_spi_dev == NULL)
    {
      printf("[SPIFLASH] ERROR: ls2k300_spiio_initialize failed\n");
      return -ENODEV;
    }

  /* Configure SPI */

  SPI_SETMODE(g_spi_dev, SPIFLASH_SPI_MODE);
  SPI_SETBITS(g_spi_dev, SPIFLASH_SPI_BITS);
  SPI_SETFREQUENCY(g_spi_dev, SPIFLASH_SPI_FREQ);

  printf("[SPIFLASH] SPI configured: mode=%d, bits=%d, freq=%d Hz\n",
         SPIFLASH_SPI_MODE, SPIFLASH_SPI_BITS, SPIFLASH_SPI_FREQ);

  usleep(20000);  /* 20ms settle */

  /* Read JEDEC ID */

  spiflash_read_jedec_id(id);
  printf("[SPIFLASH] JEDEC ID: %02X %02X %02X\n", id[0], id[1], id[2]);

  if (!spiflash_id_valid(id))
    {
      printf("[SPIFLASH] ERROR: No valid SPI Flash detected!\n");
      printf("[SPIFLASH] Check wiring and CS pin mapping.\n");
      return -ENODEV;
    }

  /* Calculate capacity and test address */

  capacity = spiflash_capacity_bytes(id);
  if (capacity >= SPIFLASH_SECTOR_SIZE * 2)
    {
      sector_addr = capacity - SPIFLASH_SECTOR_SIZE;
    }
  else
    {
      sector_addr = 0;
    }

  test_addr = sector_addr + SPIFLASH_TEST_OFFSET;

  if (capacity != 0)
    {
      printf("[SPIFLASH] Capacity: %u bytes (%u KB)\n",
             capacity, capacity / 1024);
    }
  else
    {
      printf("[SPIFLASH] Capacity unknown from ID, use sector 0\n");
    }

  printf("[SPIFLASH] Status register: 0x%02X\n", spiflash_read_status());
  printf("[SPIFLASH] Test: erase sector 0x%06X, write/read at 0x%06X\n\n",
         (unsigned int)sector_addr, (unsigned int)test_addr);

  /* Step 1: Erase sector */

  printf("[SPIFLASH] Erasing sector 0x%06X...\n", (unsigned int)sector_addr);
  ret = spiflash_sector_erase(sector_addr);
  if (ret < 0)
    {
      printf("[SPIFLASH] ERROR: Sector erase failed: %d\n", ret);
      return ret;
    }

  printf("[SPIFLASH] Erase done, status=0x%02X\n", spiflash_read_status());

  /* Step 2: Write test pattern */

  printf("[SPIFLASH] Writing test pattern (%d bytes)...\n",
         (int)sizeof(pattern));
  ret = spiflash_page_program(test_addr, pattern, sizeof(pattern));
  if (ret < 0)
    {
      printf("[SPIFLASH] ERROR: Page program failed: %d\n", ret);
      return ret;
    }

  printf("[SPIFLASH] Program done, status=0x%02X\n", spiflash_read_status());

  /* Step 3: Read back and verify */

  memset(verify, 0, sizeof(verify));
  spiflash_read_data(test_addr, verify, sizeof(verify));

  printf("[SPIFLASH] Read back: ");
  for (i = 0; i < (int)sizeof(verify); i++)
    {
      printf("%02X ", verify[i]);
    }

  printf("\n");

  if (memcmp(pattern, verify, sizeof(pattern)) == 0)
    {
      printf("[SPIFLASH] Verify PASSED: data matches!\n");
      printf("[SPIFLASH] String: %s\n", verify);
    }
  else
    {
      printf("[SPIFLASH] Verify FAILED: data mismatch!\n");
      printf("[SPIFLASH] Expected: %s\n", pattern);
      printf("[SPIFLASH] Got:      %s\n", verify);
      return -EIO;
    }

  printf("\n[SPIFLASH] === SPI Flash Test Complete ===\n");
  return OK;
}

