109	static int spi2_wait_flag(uint32_t flag, int clear)
110	{
111	  uint32_t val;
112	  uint32_t i;
113	
114	  for (i = 0; i < SPI_WAIT_TIMEOUT_US; i++)
115	    {
116	      val = SPI_REG32(LS_SPI_IO_SR1);
117	      if (val & flag)
118	        {
119	          if (clear)
120	            {
121	              SPI_REG32(LS_SPI_IO_SR1) = flag;
122	            }
123	
124	          return 0;
125	        }
126	
127	      up_udelay(1);
128	    }
129	
130	  return -1;
131	}
132	
133	static void spi2_abort(void)
134	{
135	  uint32_t val;
136	  uint32_t i;
137	
138	  val = SPI_REG32(LS_SPI_IO_CR1);
139	  val &= ~(LS_SPI_CR1_CSTART | LS_SPI_CR1_AUTOSUS);
140	  SPI_REG32(LS_SPI_IO_CR1) = val;
141	
142	  SPI_REG32(LS_SPI_IO_CR4) = 0;
143	  SPI_REG32(LS_SPI_IO_CR3) = 0;
144	  up_udelay(10);
145	
146	  SPI_REG32(LS_SPI_IO_SR1) = LS_SPI_SR1_W1C_FLAGS;
147	
148	  for (i = 0; i < 4; i++)
149	    {
150	      if (SPI_REG32(LS_SPI_IO_SR1) & LS_SPI_SR1_RXE)
151	        {
152	          break;
153	        }
154	
155	      (void)(uint8_t)SPI_REG32(LS_SPI_IO_DR);
156	    }
157	
158	  ioctl(g_fd_cs, GPIOC_WRITE, 1);
159	  up_udelay(1);
160	}
