163	static int spi2_xfer_byte(uint8_t tx, uint8_t *rx)
164	{
165	  uint32_t val;
166	  uint32_t sr1;
167	  uint32_t i;
168	
169	  val = SPI_REG32(LS_SPI_IO_CR1);
170	  val |= LS_SPI_CR1_SPE;
171	  SPI_REG32(LS_SPI_IO_CR1) = val;
172	
173	  val = SPI_REG32(LS_SPI_IO_CR1);
174	  val &= ~(LS_SPI_CR1_CSTART | LS_SPI_CR1_AUTOSUS);
175	  SPI_REG32(LS_SPI_IO_CR1) = val;
176	
177	  SPI_REG32(LS_SPI_IO_CR4) = 0;
178	  SPI_REG32(LS_SPI_IO_CR3) = 0;
179	  up_udelay(5);
180	
181	  SPI_REG32(LS_SPI_IO_SR1) = LS_SPI_SR1_W1C_FLAGS;
182	  up_udelay(1);
183	
184	  for (i = 0; i < 4; i++)
185	    {
186	      sr1 = SPI_REG32(LS_SPI_IO_SR1);
187	      if (sr1 & LS_SPI_SR1_RXE)
188	        {
189	          break;
190	        }
191	
192	      (void)(uint8_t)SPI_REG32(LS_SPI_IO_DR);
193	    }
194	
195	  SPI_REG32(LS_SPI_IO_CR3) = 0;
196	  SPI_REG32(LS_SPI_IO_DR) = tx;
197	
198	  val = SPI_REG32(LS_SPI_IO_CR1);
199	  val |= LS_SPI_CR1_CSTART;
200	  SPI_REG32(LS_SPI_IO_CR1) = val;
201	
202	  for (i = 0; i < SPI_WAIT_TIMEOUT_US; i++)
203	    {
204	      sr1 = SPI_REG32(LS_SPI_IO_SR1);
205	      if (sr1 & LS_SPI_SR1_RXA)
206	        {
207	          if (rx != NULL)
208	            {
209	              *rx = (uint8_t)SPI_REG32(LS_SPI_IO_DR);
210	            }
211	          else
212	            {
213	              (void)(uint8_t)SPI_REG32(LS_SPI_IO_DR);
214	            }
215	
216	          val = SPI_REG32(LS_SPI_IO_CR1);
217	          val &= ~(LS_SPI_CR1_CSTART | LS_SPI_CR1_AUTOSUS);
218	          SPI_REG32(LS_SPI_IO_CR1) = val;
219	          return 0;
220	        }
221	
222	      up_udelay(1);
223	    }
224	
225	  sr1 = SPI_REG32(LS_SPI_IO_SR1);
226	  if (!(sr1 & LS_SPI_SR1_RXE))
227	    {
228	      if (rx != NULL)
229	        {
230	          *rx = (uint8_t)SPI_REG32(LS_SPI_IO_DR);
231	        }
232	      else
233	        {
234	          (void)(uint8_t)SPI_REG32(LS_SPI_IO_DR);
235	        }
236	
237	      val = SPI_REG32(LS_SPI_IO_CR1);
238	      val &= ~(LS_SPI_CR1_CSTART | LS_SPI_CR1_AUTOSUS);
239	      SPI_REG32(LS_SPI_IO_CR1) = val;
240	      return 0;
241	    }
242	
243	  spi2_abort();
244	  return -1;
245	}
