296	static void mcp3204_deinit(void)
297	{
298	  if (g_fd_cs >= 0)
299	    {
300	      ioctl(g_fd_cs, GPIOC_WRITE, 1);
301	      close(g_fd_cs);
302	      g_fd_cs = -1;
303	    }
304	}
