306	static int mcp3204_read_raw(uint8_t channel, uint16_t *raw)
307	{
308	  uint8_t rx_hi = 0;
309	  uint8_t rx_lo = 0;
310	
311	  ioctl(g_fd_cs, GPIOC_WRITE, 0);
312	  up_udelay(1);
313	
314	  if (spi2_xfer_byte(0x06, NULL) != 0 ||
315	      spi2_xfer_byte((uint8_t)(channel << 6), &rx_hi) != 0 ||
316	      spi2_xfer_byte(0x00, &rx_lo) != 0)
317	    {
318	      ioctl(g_fd_cs, GPIOC_WRITE, 1);
319	      return -1;
320	    }
321	
322	  ioctl(g_fd_cs, GPIOC_WRITE, 1);
323	  up_udelay(1);
324	
325	  /* Reject 0xff - MISO stuck high, no valid data */
326	
327	  if (rx_hi == 0xff || rx_lo == 0xff)
328	    {
329	      return -1;
330	    }
331	
332	  *raw = (uint16_t)((((uint16_t)rx_hi & 0x0FU) << 8) | rx_lo);
333	  return 0;
334	}
335	
336	static int mcp3204_read_average(uint8_t channel, uint16_t *raw)
337	{
338	  uint32_t sum = 0;
339	  uint16_t value = 0;
340	  int ret;
341	  int i;
342	  int valid = 0;
343	
344	  for (i = 0; i < MCP3204_SAMPLE_COUNT * 8; i++)
345	    {
346	      ret = mcp3204_read_raw(channel, &value);
347	      if (ret != 0)
348	        {
349	          up_mdelay(2);
350	          continue;
351	        }
352	
353	      sum += value;
354	      valid++;
355	      if (valid >= MCP3204_SAMPLE_COUNT)
356	        {
357	          break;
358	        }
359	
360	      up_mdelay(2);
361	    }
362	
363	  if (valid == 0)
364	    {
365	      return -1;
366	    }
367	
368	  *raw = (uint16_t)((sum + (valid / 2)) / valid);
369	  return 0;
370	}
371	
372	static uint32_t mcp3204_raw_to_mv(uint16_t raw)
373	{
374	  return ((uint32_t)raw * MCP3204_VREF_MV + (MCP3204_ADC_MAX / 2)) /
375	         MCP3204_ADC_MAX;
376	}
