399	    {
400	      ret = mcp3204_read_average(MCP3204_DETECT_CH, &raw);
401	      if (ret != 0)
402	        {
403	          printf("[ADC] ERROR: CH%d read: %d\n", MCP3204_DETECT_CH, ret);
404	          raw = 0;
405	        }
406	
407	      mv = mcp3204_raw_to_mv(raw);
408	
409	      printf("[ADC] %3d: CH%d raw=%4u voltage=%u.%03u V\n",
410	             round + 1, MCP3204_DETECT_CH, raw, mv / 1000, mv % 1000);
411	
412	      up_mdelay(500);
413	    }
