90	  if (ret < 0)
91	    {
92	      printf("[SPIFLASH] ERROR: pinctrl failed for GPIO%d\n",
93	             SPIFLASH_CS_GPIO);
94	      return ret;
95	    }
96	
97	  /* Open GPIO device */
98	
99	  snprintf(path, sizeof(path), "/dev/gpio%d", SPIFLASH_CS_GPIO);
100	  fd = open(path, O_RDWR);
101	  if (fd < 0)
102	    {
103	      printf("[SPIFLASH] ERROR: open %s failed: %d\n", path, errno);
104	      return -errno;
105	    }
106	
107	  /* Configure as output */
108	
109	  ret = ioctl(fd, GPIOC_SETPINTYPE, (unsigned long)GPIO_OUTPUT_PIN);
110	  if (ret < 0)
111	    {
112	      printf("[SPIFLASH] ERROR: GPIOC_SETPINTYPE(OUTPUT) on GPIO%d: %d\n",
113	             SPIFLASH_CS_GPIO, errno);
114	      close(fd);
115	      return -errno;
116	    }
117	
118	  /* Default high (deselected) */
119	
120	  ret = ioctl(fd, GPIOC_WRITE, (unsigned long)true);
121	  if (ret < 0)
122	    {
123	      printf("[SPIFLASH] ERROR: GPIOC_WRITE on GPIO%d: %d\n",
124	             SPIFLASH_CS_GPIO, errno);
125	      close(fd);
126	      return -errno;
127	    }
128	
129	  close(fd);
130	  return OK;
131	}
132	
133	static void spiflash_cs_select(void)
134	{
135	  char path[32];
136	  int fd;
137	
138	  snprintf(path, sizeof(path), "/dev/gpio%d", SPIFLASH_CS_GPIO);
139	  fd = open(path, O_RDWR);
140	  if (fd >= 0)
141	    {
142	      ioctl(fd, GPIOC_WRITE, (unsigned long)false);  /* Active low */
143	      close(fd);
144	    }
145	
146	  usleep(1);
147	}
148	
149	static void spiflash_cs_deselect(void)
150	{
151	  char path[32];
152	  int fd;
153	
154	  snprintf(path, sizeof(path), "/dev/gpio%d", SPIFLASH_CS_GPIO);
155	  fd = open(path, O_RDWR);
156	  if (fd >= 0)
157	    {
158	      ioctl(fd, GPIOC_WRITE, (unsigned long)true);  /* High = deselected */
159	      close(fd);
160	    }
161	
162	  usleep(1);
163	}
164	
165	/****************************************************************************
166	 * Private Functions - SPI Transfer
167	 ****************************************************************************/
168	
169	static uint8_t spiflash_xfer_byte(uint8_t tx)
170	{
171	  uint32_t rx;
172	
173	  rx = SPI_EXCHANGE(g_spi_dev, &tx, NULL, 1);
174	  return (uint8_t)(rx & 0xff);
175	}
176	
177	/****************************************************************************
178	 * Private Functions - SPI Flash Operations
179	 ****************************************************************************/
180	
181	static void spiflash_read_jedec_id(uint8_t id[3])
182	{
183	  spiflash_cs_select();
184	  spiflash_xfer_byte(SPIFLASH_CMD_READ_JEDEC_ID);
185	  id[0] = spiflash_xfer_byte(0xff);
186	  id[1] = spiflash_xfer_byte(0xff);
187	  id[2] = spiflash_xfer_byte(0xff);
188	  spiflash_cs_deselect();
189	}
190	
191	static int spiflash_id_valid(const uint8_t id[3])
192	{
193	  if ((id[0] == 0x00 && id[1] == 0x00 && id[2] == 0x00) ||
194	      (id[0] == 0xff && id[1] == 0xff && id[2] == 0xff))
195	    {
196	      return 0;
197	    }
198	
199	  return 1;
200	}
201	
202	static uint8_t spiflash_read_status(void)
203	{
204	  uint8_t status;
205	
206	  spiflash_cs_select();
207	  spiflash_xfer_byte(SPIFLASH_CMD_READ_STATUS);
208	  status = spiflash_xfer_byte(0xff);
209	  spiflash_cs_deselect();
210	
211	  return status;
212	}
213	
214	static void spiflash_write_enable(void)
215	{
216	  spiflash_cs_select();
217	  spiflash_xfer_byte(SPIFLASH_CMD_WRITE_ENABLE);
218	  spiflash_cs_deselect();
219	}
220	
221	static int spiflash_wait_ready(FAR const char *op)
222	{
223	  uint8_t status = 0xff;
224	  int i;
225	
226	  for (i = 0; i < SPIFLASH_WAIT_TIMEOUT_MS / 10; i++)
227	    {
228	      status = spiflash_read_status();
229	      if ((status & SPIFLASH_STATUS_WIP) == 0)
230	        {
231	          return OK;
232	        }
233	
234	      usleep(10000);  /* 10ms */
235	    }
236	
237	  printf("[SPIFLASH] %s timeout, status=0x%02x\n", op, status);
238	  return -ETIMEDOUT;
239	}
240	
241	static int spiflash_sector_erase(uint32_t addr)
242	{
243	  spiflash_write_enable();
244	
245	  spiflash_cs_select();
246	  spiflash_xfer_byte(SPIFLASH_CMD_SECTOR_ERASE_4K);
247	  spiflash_xfer_byte((uint8_t)(addr >> 16));
248	  spiflash_xfer_byte((uint8_t)(addr >> 8));
249	  spiflash_xfer_byte((uint8_t)addr);
250	  spiflash_cs_deselect();
251	
252	  return spiflash_wait_ready("erase");
253	}
254	
255	static int spiflash_page_program(uint32_t addr, FAR const uint8_t *data,
256	                                 uint32_t len)
257	{
258	  uint32_t i;
259	
260	  spiflash_write_enable();
261	
262	  spiflash_cs_select();
263	  spiflash_xfer_byte(SPIFLASH_CMD_PAGE_PROGRAM);
264	  spiflash_xfer_byte((uint8_t)(addr >> 16));
265	  spiflash_xfer_byte((uint8_t)(addr >> 8));
266	  spiflash_xfer_byte((uint8_t)addr);
267	
268	  for (i = 0; i < len; i++)
269	    {
270	      spiflash_xfer_byte(data[i]);
271	    }
272	
273	  spiflash_cs_deselect();
274	
275	  return spiflash_wait_ready("program");
276	}
277	
278	static void spiflash_read_data(uint32_t addr, FAR uint8_t *data,
279	                               uint32_t len)
280	{
281	  uint32_t i;
282	
283	  spiflash_cs_select();
284	  spiflash_xfer_byte(SPIFLASH_CMD_READ_DATA);
285	  spiflash_xfer_byte((uint8_t)(addr >> 16));
286	  spiflash_xfer_byte((uint8_t)(addr >> 8));
287	  spiflash_xfer_byte((uint8_t)addr);
288	
289	  for (i = 0; i < len; i++)
290	    {
291	      data[i] = spiflash_xfer_byte(0xff);
292	    }
293	
294	  spiflash_cs_deselect();
295	}
296	
297	static uint32_t spiflash_capacity_bytes(const uint8_t id[3])
298	{
299	  if (id[2] < 16 || id[2] > 30)
300	    {
301	      return 0;
302	    }
303	
304	  return (uint32_t)(1UL << id[2]);
305	}
306	
307	/****************************************************************************
308	 * Public Functions
309	 ****************************************************************************/
310	
311	int test_spiflash(void)
312	{
313	  uint8_t id[3] = {0};
314	  uint8_t pattern[] = {
315	    'L', 'O', 'O', 'N', 'G', '-', 'H', 'A',
316	    'T', '-', 'S', 'P', 'I', '-', 'F', 'L', '\0'
317	  };
318	  uint8_t verify[sizeof(pattern)];
319	  uint32_t capacity;
320	  uint32_t sector_addr;
321	  uint32_t test_addr;
322	  int ret;
323	  int i;
324	
325	  printf("[SPIFLASH] === SPI Flash Test (SPIIO2 + GPIO%d CS) ===\n",
326	         SPIFLASH_CS_GPIO);
327	  printf("[SPIFLASH] SCK=GPIO64 MISO=GPIO65 MOSI=GPIO66 CSN=GPIO%d\n",
328	         SPIFLASH_CS_GPIO);
329	
330	  /* Initialize chip select GPIO */
331	
332	  ret = spiflash_cs_init();
333	  if (ret < 0)
334	    {
335	      printf("[SPIFLASH] ERROR: CS init failed: %d\n", ret);
336	      return ret;
337	    }
338	
339	  printf("[SPIFLASH] CS GPIO%d initialized (default high)\n",
340	         SPIFLASH_CS_GPIO);
341	
342	  /* Initialize SPI IO controller */
343	
344	  printf("[SPIFLASH] Initializing SPIIO2...\n");
345	  g_spi_dev = ls2k300_spiio_initialize(SPIFLASH_SPI_PORT);
346	  if (g_spi_dev == NULL)
347	    {
348	      printf("[SPIFLASH] ERROR: ls2k300_spiio_initialize failed\n");
349	      return -ENODEV;
350	    }
351	
352	  /* Configure SPI */
353	
354	  SPI_SETMODE(g_spi_dev, SPIFLASH_SPI_MODE);
355	  SPI_SETBITS(g_spi_dev, SPIFLASH_SPI_BITS);
356	  SPI_SETFREQUENCY(g_spi_dev, SPIFLASH_SPI_FREQ);
357	
358	  printf("[SPIFLASH] SPI configured: mode=%d, bits=%d, freq=%d Hz\n",
359	         SPIFLASH_SPI_MODE, SPIFLASH_SPI_BITS, SPIFLASH_SPI_FREQ);
360	
361	  usleep(20000);  /* 20ms settle */
362	
363	  /* Read JEDEC ID */
364	
365	  spiflash_read_jedec_id(id);
366	  printf("[SPIFLASH] JEDEC ID: %02X %02X %02X\n", id[0], id[1], id[2]);
367	
368	  if (!spiflash_id_valid(id))
369	    {
370	      printf("[SPIFLASH] ERROR: No valid SPI Flash detected!\n");
371	      printf("[SPIFLASH] Check wiring and CS pin mapping.\n");
372	      return -ENODEV;
373	    }
374	
375	  /* Calculate capacity and test address */
376	
377	  capacity = spiflash_capacity_bytes(id);
378	  if (capacity >= SPIFLASH_SECTOR_SIZE * 2)
379	    {
380	      sector_addr = capacity - SPIFLASH_SECTOR_SIZE;
381	    }
382	  else
383	    {
384	      sector_addr = 0;
385	    }
386	
387	  test_addr = sector_addr + SPIFLASH_TEST_OFFSET;
388	
389	  if (capacity != 0)
390	    {
391	      printf("[SPIFLASH] Capacity: %u bytes (%u KB)\n",
392	             capacity, capacity / 1024);
393	    }
394	  else
395	    {
396	      printf("[SPIFLASH] Capacity unknown from ID, use sector 0\n");
397	    }
398	
399	  printf("[SPIFLASH] Status register: 0x%02X\n", spiflash_read_status());
400	  printf("[SPIFLASH] Test: erase sector 0x%06X, write/read at 0x%06X\n\n",
401	         (unsigned int)sector_addr, (unsigned int)test_addr);
402	
403	  /* Step 1: Erase sector */
404	
405	  printf("[SPIFLASH] Erasing sector 0x%06X...\n", (unsigned int)sector_addr);
406	  ret = spiflash_sector_erase(sector_addr);
407	  if (ret < 0)
408	    {
409	      printf("[SPIFLASH] ERROR: Sector erase failed: %d\n", ret);
410	      return ret;
411	    }
412	
413	  printf("[SPIFLASH] Erase done, status=0x%02X\n", spiflash_read_status());
414	
415	  /* Step 2: Write test pattern */
416	
417	  printf("[SPIFLASH] Writing test pattern (%d bytes)...\n",
418	         (int)sizeof(pattern));
419	  ret = spiflash_page_program(test_addr, pattern, sizeof(pattern));
420	  if (ret < 0)
421	    {
422	      printf("[SPIFLASH] ERROR: Page program failed: %d\n", ret);
423	      return ret;
424	    }
425	
426	  printf("[SPIFLASH] Program done, status=0x%02X\n", spiflash_read_status());
427	
428	  /* Step 3: Read back and verify */
429	
430	  memset(verify, 0, sizeof(verify));
431	  spiflash_read_data(test_addr, verify, sizeof(verify));
432	
433	  printf("[SPIFLASH] Read back: ");
434	  for (i = 0; i < (int)sizeof(verify); i++)
435	    {
436	      printf("%02X ", verify[i]);
437	    }
438	
439	  printf("\n");
440	
441	  if (memcmp(pattern, verify, sizeof(pattern)) == 0)
442	    {
443	      printf("[SPIFLASH] Verify PASSED: data matches!\n");
444	      printf("[SPIFLASH] String: %s\n", verify);
445	    }
446	  else
447	    {
448	      printf("[SPIFLASH] Verify FAILED: data mismatch!\n");
449	      printf("[SPIFLASH] Expected: %s\n", pattern);
450	      printf("[SPIFLASH] Got:      %s\n", verify);
451	      return -EIO;
452	    }
453	
454	  printf("\n[SPIFLASH] === SPI Flash Test Complete ===\n");
455	  return OK;
456	}
