306	
307	  CFG5_REG |= (0x3u << 17);
308	
309	  /* CFG3: master, full duplex, software CS mode */
310	
311	  SPI_REG32(LS_SPI_IO_CFG3) = LS_SPI_CFG3_MSTR | LS_SPI_CFG3_DIE |
312	                               LS_SPI_CFG3_DOE | LS_SPI_CFG3_SSMODE_SW;
313	
314	  /* CFG1: 8-bit frame, SPI mode 0 */
315	
316	  SPI_REG32(LS_SPI_IO_CFG1) = LS_SPI_CFG1_DSIZE_8BIT;
317	
318	  /* CFG2: baud rate divider */
319	
320	  brint = SPI_APB_HZ / SPI_CLOCK_HZ;
321	  if (brint < 2)
322	    {
323	      brint = 2;
324	    }
325	
326	  if (brint > 255)
327	    {
328	      brint = 255;
329	    }
330	
331	  SPI_REG32(LS_SPI_IO_CFG2) = brint << LS_SPI_CFG2_BRINT_SHIFT;
332	
333	  /* CR1: enable SPI */
334	
335	  SPI_REG32(LS_SPI_IO_CR1) = LS_SPI_CR1_SPE;
336	
337	  return OK;
338	}
