440	/****************************************************************************
441	 * Private Functions - SPI Flash (CS on GPIO85)
442	 ****************************************************************************/
443	
444	static void flash_cs_select(void)
445	{
446	  gpio_write(g_fd_flash_cs, false);
447	  up_udelay(1);
448	}
449	
450	static void flash_cs_deselect(void)
451	{
452	  gpio_write(g_fd_flash_cs, true);
453	  up_udelay(1);
454	}
455	
456	static uint8_t flash_xfer(uint8_t tx)
457	{
458	  uint8_t rx = 0;
459	  spi2_xfer_byte(tx, &rx);
460	  return rx;
461	}
462	
463	static void flash_read_jedec_id(uint8_t id[3])
464	{
465	  flash_cs_select();
466	  flash_xfer(SPIFLASH_CMD_READ_JEDEC_ID);
467	  id[0] = flash_xfer(0xff);
468	  id[1] = flash_xfer(0xff);
469	  id[2] = flash_xfer(0xff);
470	  flash_cs_deselect();
471	}
472	
473	static int flash_id_valid(const uint8_t id[3])
474	{
475	  if ((id[0] == 0x00 && id[1] == 0x00 && id[2] == 0x00) ||
476	      (id[0] == 0xff && id[1] == 0xff && id[2] == 0xff))
477	    {
478	      return 0;
479	    }
480	
481	  return 1;
482	}
483	
484	static uint8_t flash_read_status(void)
485	{
486	  uint8_t status;
487	
488	  flash_cs_select();
489	  flash_xfer(SPIFLASH_CMD_READ_STATUS);
490	  status = flash_xfer(0xff);
491	  flash_cs_deselect();
492	
493	  return status;
494	}
495	
496	static void flash_write_enable(void)
497	{
498	  flash_cs_select();
499	  flash_xfer(SPIFLASH_CMD_WRITE_ENABLE);
500	  flash_cs_deselect();
501	}
502	
503	static int flash_wait_ready(FAR const char *op)
504	{
505	  uint8_t status = 0xff;
506	  int i;
507	
508	  for (i = 0; i < 500; i++)
509	    {
510	      status = flash_read_status();
511	      if ((status & SPIFLASH_STATUS_WIP) == 0)
512	        {
513	          return OK;
514	        }
515	
516	      up_mdelay(10);
517	    }
518	
519	  printf("[SPIFLASH] %s timeout, status=0x%02x\n", op, status);
520	  return -ETIMEDOUT;
521	}
522	
523	static int flash_sector_erase(uint32_t addr)
524	{
525	  flash_write_enable();
526	
527	  flash_cs_select();
528	  flash_xfer(SPIFLASH_CMD_SECTOR_ERASE_4K);
529	  flash_xfer((uint8_t)(addr >> 16));
530	  flash_xfer((uint8_t)(addr >> 8));
531	  flash_xfer((uint8_t)addr);
532	  flash_cs_deselect();
533	
534	  return flash_wait_ready("erase");
535	}
536	
537	static int flash_page_program(uint32_t addr, FAR const uint8_t *data,
538	                              uint32_t len)
539	{
540	  uint32_t i;
541	
542	  flash_write_enable();
543	
544	  flash_cs_select();
545	  flash_xfer(SPIFLASH_CMD_PAGE_PROGRAM);
546	  flash_xfer((uint8_t)(addr >> 16));
547	  flash_xfer((uint8_t)(addr >> 8));
548	  flash_xfer((uint8_t)addr);
549	
550	  for (i = 0; i < len; i++)
551	    {
552	      flash_xfer(data[i]);
553	    }
554	
555	  flash_cs_deselect();
556	
557	  return flash_wait_ready("program");
558	}
559	
560	static void flash_read_data(uint32_t addr, FAR uint8_t *data, uint32_t len)
561	{
562	  uint32_t i;
563	
564	  flash_cs_select();
565	  flash_xfer(SPIFLASH_CMD_READ_DATA);
566	  flash_xfer((uint8_t)(addr >> 16));
567	  flash_xfer((uint8_t)(addr >> 8));
568	  flash_xfer((uint8_t)addr);
569	
570	  for (i = 0; i < len; i++)
571	    {
572	      data[i] = flash_xfer(0xff);
573	    }
574	
575	  flash_cs_deselect();
576	}
577	
578	static uint32_t flash_capacity_bytes(const uint8_t id[3])
579	{
580	  if (id[2] < 16 || id[2] > 30)
581	    {
582	      return 0;
583	    }
584	
585	  return (uint32_t)(1UL << id[2]);
586	}
