588	/****************************************************************************
589	 * Private Functions - MCP3204 ADC (CS on GPIO67)
590	 ****************************************************************************/
591	
592	static void adc_cs_select(void)
593	{
594	  gpio_write(g_fd_adc_cs, false);
595	  up_udelay(1);
596	}
597	
598	static void adc_cs_deselect(void)
599	{
600	  gpio_write(g_fd_adc_cs, true);
601	  up_udelay(1);
602	}
603	
604	static int mcp3204_read_raw(uint8_t channel, uint16_t *raw)
605	{
606	  uint8_t rx_hi = 0;
607	  uint8_t rx_lo = 0;
608	
609	  adc_cs_select();
610	
611	  if (spi2_xfer_byte(0x06, NULL) != 0 ||
612	      spi2_xfer_byte((uint8_t)(channel << 6), &rx_hi) != 0 ||
613	      spi2_xfer_byte(0x00, &rx_lo) != 0)
614	    {
615	      adc_cs_deselect();
616	      return -1;
617	    }
618	
619	  adc_cs_deselect();
620	
621	  /* Reject 0xff - MISO stuck high, no valid data */
622	
623	  if (rx_hi == 0xff || rx_lo == 0xff)
624	    {
625	      return -1;
626	    }
627	
628	  *raw = (uint16_t)((((uint16_t)rx_hi & 0x0fU) << 8) | rx_lo);
629	  return 0;
630	}
631	
632	static int mcp3204_read_average(uint8_t channel, uint16_t *raw)
633	{
634	  uint32_t sum = 0;
635	  uint16_t value = 0;
636	  int ret;
637	  int i;
638	  int valid = 0;
639	
640	  for (i = 0; i < MCP3204_SAMPLE_COUNT * 8; i++)
641	    {
642	      ret = mcp3204_read_raw(channel, &value);
643	      if (ret != 0)
644	        {
645	          up_mdelay(2);
646	          continue;
647	        }
648	
649	      sum += value;
650	      valid++;
651	      if (valid >= MCP3204_SAMPLE_COUNT)
652	        {
653	          break;
654	        }
655	
656	      up_mdelay(2);
657	    }
658	
659	  if (valid == 0)
660	    {
661	      return -1;
662	    }
663	
664	  *raw = (uint16_t)((sum + (valid / 2)) / valid);
665	  return 0;
666	}
667	
668	static uint32_t mcp3204_raw_to_mv(uint16_t raw)
669	{
670	  return ((uint32_t)raw * MCP3204_VREF_MV + (MCP3204_ADC_MAX / 2)) /
671	         MCP3204_ADC_MAX;
672	}
