674	/****************************************************************************
675	 * Private Functions - Flash Data Operations
676	 ****************************************************************************/
677	
678	static void spiflash_print_stored_data(uint32_t base_addr)
679	{
680	  uint8_t magic;
681	  uint8_t count;
682	  uint8_t buf[2];
683	  uint16_t raw;
684	  uint32_t mv;
685	  int i;
686	  int ret;
687	
688	  printf("[SPIFLASH] ---- Stored ADC Data in Flash ----\n");
689	
690	  flash_read_data(base_addr + FLASH_MAGIC_ADDR, &magic, 1);
691	  printf("[SPIFLASH] Magic: 0x%02X (%s)\n",
692	         magic, (magic == FLASH_MAGIC_VALUE) ? "valid" : "invalid/empty");
693	
694	  if (magic != FLASH_MAGIC_VALUE)
695	    {
696	      printf("[SPIFLASH] No valid data stored yet\n");
697	      printf("[SPIFLASH] ---- End ----\n\n");
698	      return;
699	    }
700	
701	  flash_read_data(base_addr + FLASH_COUNT_ADDR, &count, 1);
702	  printf("[SPIFLASH] Stored readings: %u\n", count);
703	
704	  if (count > FLASH_MAX_READINGS)
705	    {
706	      count = FLASH_MAX_READINGS;
707	    }
708	
709	  for (i = 0; i < count; i++)
710	    {
711	      flash_read_data(base_addr + FLASH_DATA_ADDR + i * 2, buf, 2);
712	      raw = ((uint16_t)buf[0] << 8) | buf[1];
713	      mv = mcp3204_raw_to_mv(raw);
714	      printf("[SPIFLASH]   [%d] raw=%4u  voltage=%u.%03u V\n",
715	             i, raw, mv / 1000, mv % 1000);
716	    }
717	
718	  printf("[SPIFLASH] ---- End ----\n\n");
719	}
720	
721	static int spiflash_save_readings(uint32_t base_addr,
722	                                  const uint16_t *readings, int count)
723	{
724	  uint8_t buf[FLASH_MAX_READINGS * 2];
725	  uint8_t verify_buf[2];
726	  uint16_t stored;
727	  int i;
728	  int ret;
729	
730	  if (count > FLASH_MAX_READINGS)
731	    {
732	      count = FLASH_MAX_READINGS;
733	    }
734	
735	  /* Pack readings into byte array (big-endian uint16_t) */
736	
737	  for (i = 0; i < count; i++)
738	    {
739	      buf[i * 2]     = (uint8_t)(readings[i] >> 8);
740	      buf[i * 2 + 1] = (uint8_t)(readings[i] & 0xff);
741	    }
742	
743	  /* Erase sector first */
744	
745	  printf("[SPIFLASH] Erasing sector 0x%06X...\n",
746	         (unsigned int)(base_addr & ~(SPIFLASH_SECTOR_SIZE - 1)));
747	  ret = flash_sector_erase(base_addr & ~(SPIFLASH_SECTOR_SIZE - 1));
748	  if (ret < 0)
749	    {
750	      printf("[SPIFLASH] ERROR: erase failed: %d\n", ret);
751	      return ret;
752	    }
753	
754	  /* Write count */
755	
756	  ret = flash_page_program(base_addr + FLASH_COUNT_ADDR, &count, 1);
757	  if (ret < 0)
758	    {
759	      printf("[SPIFLASH] ERROR: write count: %d\n", ret);
760	      return ret;
761	    }
762	
763	  /* Write data */
764	
765	  ret = flash_page_program(base_addr + FLASH_DATA_ADDR, buf, count * 2);
766	  if (ret < 0)
767	    {
768	      printf("[SPIFLASH] ERROR: write data: %d\n", ret);
769	      return ret;
770	    }
771	
772	  /* Write magic last (signals data is valid) */
773	
774	  buf[0] = FLASH_MAGIC_VALUE;
775	  ret = flash_page_program(base_addr + FLASH_MAGIC_ADDR, buf, 1);
776	  if (ret < 0)
777	    {
778	      printf("[SPIFLASH] ERROR: write magic: %d\n", ret);
779	      return ret;
780	    }
781	
782	  /* Verify */
783	
784	  for (i = 0; i < count; i++)
785	    {
786	      flash_read_data(base_addr + FLASH_DATA_ADDR + i * 2, verify_buf, 2);
787	      stored = ((uint16_t)verify_buf[0] << 8) | verify_buf[1];
788	      if (stored != readings[i])
789	        {
790	          printf("[SPIFLASH] ERROR: verify[%d] mismatch: "
791	                 "expected %u, got %u\n", i, readings[i], stored);
792	          return -EIO;
793	        }
794	    }
795	
796	  printf("[SPIFLASH] Saved and verified %d readings\n", count);
797	  return OK;
798	}
799	
800	/****************************************************************************
801	 * Private Functions - Read ADC and Save
802	 ****************************************************************************/
803	
804	static int read_adc_and_save(uint32_t flash_addr)
805	{
806	  uint16_t readings[FLASH_MAX_READINGS];
807	  uint16_t raw;
808	  uint32_t mv;
809	  int ret;
810	  int i;
811	
812	  printf("\n[SPIFLASH] === KEY1 pressed: reading ADC CH%d x%d ===\n",
813	         MCP3204_CHANNEL, FLASH_MAX_READINGS);
814	
815	  /* Read ADC 5 times */
816	
817	  for (i = 0; i < FLASH_MAX_READINGS; i++)
818	    {
819	      usleep(300000);  /* 300ms between readings */
820	
821	      ret = mcp3204_read_average(MCP3204_CHANNEL, &raw);
822	      if (ret < 0)
823	        {
824	          printf("[SPIFLASH]   [%d] ADC read failed: %d\n", i, ret);
825	          readings[i] = 0;
826	        }
827	      else
828	        {
829	          readings[i] = raw;
830	          mv = mcp3204_raw_to_mv(raw);
831	          printf("[SPIFLASH]   [%d] CH%d raw=%4u  voltage=%u.%03u V\n",
832	                 i, MCP3204_CHANNEL, raw, mv / 1000, mv % 1000);
833	        }
834	    }
835	
836	  /* Save to SPI Flash */
837	
838	  printf("[SPIFLASH] Saving readings to SPI Flash...\n");
839	  ret = spiflash_save_readings(flash_addr, readings, FLASH_MAX_READINGS);
840	  if (ret < 0)
841	    {
842	      printf("[SPIFLASH] Save failed!\n");
843	      return ret;
844	    }
845	
846	  /* Read back and print */
847	
848	  printf("[SPIFLASH] Verifying flash contents:\n");
849	  spiflash_print_stored_data(flash_addr);
850	
851	  return OK;
852	}
