855	 * Public Functions
856	 ****************************************************************************/
857	
858	int test_spiflash(void)
859	{
860	  uint8_t id[3] = {0};
861	  uint32_t capacity;
862	  uint32_t sector_addr;
863	  uint32_t flash_addr;
864	  bool key1_last;
865	  bool key2_last;
866	  int ret;
867	
868	  printf("[SPIFLASH] === SPI Flash + ADC Test ===\n");
869	  printf("[SPIFLASH] SPI2 bus: SCK=GPIO64 MISO=GPIO65 MOSI=GPIO66\n");
870	  printf("[SPIFLASH] MCP3204 ADC CS=GPIO%d (CH%d)\n",
871	         ADC_CS_PIN, MCP3204_CHANNEL);
872	  printf("[SPIFLASH] SPI Flash CS=GPIO%d\n", FLASH_CS_PIN);
873	  printf("[SPIFLASH] KEY1=GPIO%d: read ADC x5, save to flash\n", KEY1_GPIO);
874	  printf("[SPIFLASH] KEY2=GPIO%d: exit\n\n", KEY2_GPIO);
875	
876	  /* Initialize GPIO pins */
877	
878	  g_fd_flash_cs = gpio_open_output(FLASH_CS_PIN);
879	  if (g_fd_flash_cs < 0)
880	    {
881	      return g_fd_flash_cs;
882	    }
883	
884	  g_fd_adc_cs = gpio_open_output(ADC_CS_PIN);
885	  if (g_fd_adc_cs < 0)
886	    {
887	      close(g_fd_flash_cs);
888	      return g_fd_adc_cs;
889	    }
890	
891	  g_fd_key1 = gpio_open_input(KEY1_GPIO);
892	  if (g_fd_key1 < 0)
893	    {
894	      close(g_fd_adc_cs);
895	      close(g_fd_flash_cs);
896	      return g_fd_key1;
897	    }
898	
899	  g_fd_key2 = gpio_open_input(KEY2_GPIO);
900	  if (g_fd_key2 < 0)
901	    {
902	      close(g_fd_key1);
903	      close(g_fd_adc_cs);
904	      close(g_fd_flash_cs);
905	      return g_fd_key2;
906	    }
907	
908	  printf("[SPIFLASH] GPIO initialized: FL_CS=GPIO%d ADC_CS=GPIO%d\n",
909	         FLASH_CS_PIN, ADC_CS_PIN);
910	  printf("[SPIFLASH] GPIO initialized: KEY1=GPIO%d KEY2=GPIO%d\n",
911	         KEY1_GPIO, KEY2_GPIO);
912	
913	  /* Initialize SPI2 controller */
914	
915	  ret = spi2_init();
916	  if (ret < 0)
917	    {
918	      printf("[SPIFLASH] ERROR: SPI2 init failed: %d\n", ret);
919	      goto cleanup;
920	    }
921	
922	  printf("[SPIFLASH] SPI2 initialized (1MHz, mode 0, 8-bit)\n");
923	  up_mdelay(20);
924	
925	  /* Detect SPI Flash */
926	
927	  flash_read_jedec_id(id);
928	  printf("[SPIFLASH] Flash JEDEC ID: %02X %02X %02X\n",
929	         id[0], id[1], id[2]);
930	
931	  if (!flash_id_valid(id))
932	    {
933	      printf("[SPIFLASH] ERROR: No valid SPI Flash detected!\n");
934	      printf("[SPIFLASH] Check wiring and CS pin mapping.\n");
935	      ret = -ENODEV;
936	      goto cleanup;
937	    }
938	
939	  capacity = flash_capacity_bytes(id);
940	  if (capacity >= SPIFLASH_SECTOR_SIZE * 2)
941	    {
942	      sector_addr = capacity - SPIFLASH_SECTOR_SIZE;
943	    }
944	  else
945	    {
946	      sector_addr = 0;
947	    }
948	
949	  flash_addr = sector_addr + SPIFLASH_TEST_OFFSET;
950	
951	  if (capacity != 0)
952	    {
953	      printf("[SPIFLASH] Flash capacity: %u bytes (%u KB)\n",
954	             capacity, capacity / 1024);
955	    }
956	
957	  printf("[SPIFLASH] Flash status: 0x%02X\n", flash_read_status());
958	  printf("[SPIFLASH] Data sector: 0x%06X, data addr: 0x%06X\n\n",
959	         (unsigned int)sector_addr, (unsigned int)flash_addr);
960	
961	  /* Read and print current flash contents */
962	
963	  printf("[SPIFLASH] Reading current flash contents...\n");
964	  spiflash_print_stored_data(flash_addr);
965	
966	  /* Initialize key states */
967	
968	  key1_last = gpio_read(g_fd_key1);
969	  key2_last = gpio_read(g_fd_key2);
970	  printf("[SPIFLASH] KEY1(GPIO%d) ready, waiting for press...\n", KEY1_GPIO);
971	  printf("[SPIFLASH] KEY2(GPIO%d) ready, press to exit\n\n", KEY2_GPIO);
972	
973	  /* Main loop */
974	
975	  while (1)
976	    {
977	      if (key_scan(g_fd_key1, &key1_last))
978	        {
979	          ret = read_adc_and_save(flash_addr);
980	          if (ret < 0)
981	            {
982	              printf("[SPIFLASH] read_adc_and_save failed: %d\n", ret);
