/****************************************************************************
 * apps/examples/ls_driver_test/test_spiflash.c
 *
 * SPI Flash + MCP3204 ADC combined test for LS2K300 (LOONG-HAT).
 *
 * Function:
 *   1. On startup, read and print stored ADC data from SPI Flash
 *   2. Press KEY1 (GPIO87): read MCP3204 ADC CH0 five times,
 *      save readings to SPI Flash, then read back and print
 *   3. Press KEY2 (GPIO86): exit program
 *
 * Hardware (LOONG-HAT 40PIN header, shared SPI2 bus):
 *   - SCK   : GPIO64 / J12 Pin23 -> spi2_clk  (MAIN_FUNC)
 *   - MISO  : GPIO65 / J12 Pin21 -> spi2_miso (MAIN_FUNC)
 *   - MOSI  : GPIO66 / J12 Pin19 -> spi2_mosi (MAIN_FUNC)
 *   - ADC_CS: GPIO67 / J12 Pin24 -> MCP3204 CS (GPIO)
 *   - FL_CS : GPIO85 / J12 Pin26 -> SPI Flash CS (GPIO)
 *   - KEY1  : GPIO87 (active-low, read ADC & save)
 *   - KEY2  : GPIO86 (active-low, exit)
 *
 * Flash memory layout (last 4KB sector):
 *   0x0000        - magic (0xA5 = valid data)
 *   0x0001        - number of stored readings (uint8_t)
 *   0x0010..0x0019 - 5 x uint16_t ADC raw values (12-bit, 0..4095)
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <sys/ioctl.h>
#include <stdio.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <stdint.h>

#include <nuttx/ioexpander/gpio.h>
#include <nuttx/arch.h>

#include "ls_driver_test.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* SPI2 controller base (uncached, PHYS 0x1610c000) */

#define SPI2_BASE               (0x8000000000000000UL | 0x1610c000UL)

/* GENERAL_CFG5 for SPI2/3 clock gate */

#define LS_GENERAL_CFG5_ADDR    (0x8000000000000000UL | 0x16000114UL)

/* SPI IO register offsets (LS2K300 manual ch.10) */

#define LS_SPI_IO_CR1           0x00
#define LS_SPI_IO_CR3           0x08
#define LS_SPI_IO_CR4           0x0c
#define LS_SPI_IO_SR1           0x14
#define LS_SPI_IO_CFG1          0x20
#define LS_SPI_IO_CFG2          0x24
#define LS_SPI_IO_CFG3          0x28
#define LS_SPI_IO_DR            0x40

/* CR1 bits */

#define LS_SPI_CR1_SPE          (1U << 0)
#define LS_SPI_CR1_CSTART       (1U << 1)
#define LS_SPI_CR1_AUTOSUS      (1U << 2)

/* CFG1: 8-bit frame (DSIZE=7), MSB first, CPOL=0 CPHA=0 (mode 0) */

#define LS_SPI_CFG1_DSIZE_8BIT  (7U << 8)

/* CFG2: baud ratio divider */

#define LS_SPI_CFG2_BRINT_SHIFT 8

/* CFG3: master, full duplex, software CS */

#define LS_SPI_CFG3_MSTR        (1U << 0)
#define LS_SPI_CFG3_DIE         (1U << 2)
#define LS_SPI_CFG3_DOE         (1U << 3)
#define LS_SPI_CFG3_SSMODE_SW   (1U << 8)

/* SR1 status bits */

#define LS_SPI_SR1_RXA          (1U << 0)
#define LS_SPI_SR1_TXA          (1U << 1)
#define LS_SPI_SR1_RXE          (1U << 4)
#define LS_SPI_SR1_EOT          (1U << 15)

#define LS_SPI_SR1_W1C_FLAGS    (LS_SPI_SR1_EOT | (1U << 11) | \
                                 (1U << 10) | (1U << 9) | (1U << 8))

/* APB ~200MHz, use 1MHz SPI clock */

#define SPI_APB_HZ              (200UL * 1000000UL)
#define SPI_CLOCK_HZ            1000000UL
#define SPI_WAIT_TIMEOUT_US     10000U

/* GPIO pin definitions */

#define FLASH_CS_PIN            85
#define ADC_CS_PIN              67
#define KEY1_GPIO               87
#define KEY2_GPIO               86

/* MCP3204 parameters */

#define MCP3204_ADC_MAX         4095U
#define MCP3204_VREF_MV        3300U
#define MCP3204_SAMPLE_COUNT    8
#define MCP3204_CHANNEL         0

/* SPI Flash commands */

#define SPIFLASH_CMD_WRITE_ENABLE     0x06
#define SPIFLASH_CMD_READ_STATUS      0x05
#define SPIFLASH_CMD_READ_JEDEC_ID    0x9f
#define SPIFLASH_CMD_READ_DATA        0x03
#define SPIFLASH_CMD_PAGE_PROGRAM     0x02
#define SPIFLASH_CMD_SECTOR_ERASE_4K  0x20
#define SPIFLASH_STATUS_WIP           0x01

/* Flash parameters */

#define SPIFLASH_SECTOR_SIZE          4096U
#define SPIFLASH_TEST_OFFSET          0x100U

/* Flash data layout */

#define FLASH_MAGIC_ADDR              0x0000
#define FLASH_COUNT_ADDR              0x0001
#define FLASH_DATA_ADDR               0x0010
#define FLASH_MAGIC_VALUE             0xA5
#define FLASH_MAX_READINGS            5

/* Timing */

#define KEY_SCAN_DELAY_MS             10
#define KEY_DEBOUNCE_MS               20

/* Register access macros */

#define SPI_REG32(off) (*(volatile uint32_t *)(SPI2_BASE + (off)))
#define CFG5_REG      (*(volatile uint32_t *)LS_GENERAL_CFG5_ADDR)

/****************************************************************************
 * Private Data
 ****************************************************************************/

static int g_fd_flash_cs = -1;
static int g_fd_adc_cs = -1;
static int g_fd_key1 = -1;
static int g_fd_key2 = -1;

/****************************************************************************
 * Private Functions - SPI2 Hardware
 ****************************************************************************/

static void spi2_bus_reset(void)
{
  uint32_t val;
  uint32_t i;

  /* Stop any pending transfer */

  val = SPI_REG32(LS_SPI_IO_CR1);
  val &= ~(LS_SPI_CR1_CSTART | LS_SPI_CR1_AUTOSUS);
  SPI_REG32(LS_SPI_IO_CR1) = val;

  /* Clear transfer size */

  SPI_REG32(LS_SPI_IO_CR4) = 0;
  SPI_REG32(LS_SPI_IO_CR3) = 0;
  up_udelay(10);

  /* Clear all W1C status flags */

  SPI_REG32(LS_SPI_IO_SR1) = LS_SPI_SR1_W1C_FLAGS;

  /* Drain RXFIFO */

  for (i = 0; i < 4; i++)
    {
      if (SPI_REG32(LS_SPI_IO_SR1) & LS_SPI_SR1_RXE)
        {
          break;
        }

      (void)(uint8_t)SPI_REG32(LS_SPI_IO_DR);
    }

  /* Re-enable SPI */

  SPI_REG32(LS_SPI_IO_CR1) = LS_SPI_CR1_SPE;

  /* Deselect ALL chip selects to put devices back to idle */

  gpio_write(g_fd_flash_cs, true);
  gpio_write(g_fd_adc_cs, true);
  up_udelay(10);
}

static int spi2_wait_flag(uint32_t flag, int clear)
{
  uint32_t val;
  uint32_t i;

  for (i = 0; i < SPI_WAIT_TIMEOUT_US; i++)
    {
      val = SPI_REG32(LS_SPI_IO_SR1);
      if (val & flag)
        {
          if (clear)
            {
              SPI_REG32(LS_SPI_IO_SR1) = flag;
            }

          return 0;
        }

      up_udelay(1);
    }

  return -1;
}

static void spi2_abort(void)
{
  uint32_t val;
  uint32_t i;

  val = SPI_REG32(LS_SPI_IO_CR1);
  val &= ~(LS_SPI_CR1_CSTART | LS_SPI_CR1_AUTOSUS);
  SPI_REG32(LS_SPI_IO_CR1) = val;

  SPI_REG32(LS_SPI_IO_CR4) = 0;
  SPI_REG32(LS_SPI_IO_CR3) = 0;
  up_udelay(10);

  SPI_REG32(LS_SPI_IO_SR1) = LS_SPI_SR1_W1C_FLAGS;

  for (i = 0; i < 4; i++)
    {
      if (SPI_REG32(LS_SPI_IO_SR1) & LS_SPI_SR1_RXE)
        {
          break;
        }

      (void)(uint8_t)SPI_REG32(LS_SPI_IO_DR);
    }

  /* Deselect all CS on abort */

  gpio_write(g_fd_flash_cs, true);
  gpio_write(g_fd_adc_cs, true);
  up_udelay(1);
}

static int spi2_xfer_byte(uint8_t tx, uint8_t *rx)
{
  uint32_t val;
  uint32_t sr1;
  uint32_t i;

  val = SPI_REG32(LS_SPI_IO_CR1);
  val |= LS_SPI_CR1_SPE;
  SPI_REG32(LS_SPI_IO_CR1) = val;

  val = SPI_REG32(LS_SPI_IO_CR1);
  val &= ~(LS_SPI_CR1_CSTART | LS_SPI_CR1_AUTOSUS);
  SPI_REG32(LS_SPI_IO_CR1) = val;

  SPI_REG32(LS_SPI_IO_CR4) = 0;
  SPI_REG32(LS_SPI_IO_CR3) = 0;
  up_udelay(5);

  SPI_REG32(LS_SPI_IO_SR1) = LS_SPI_SR1_W1C_FLAGS;
  up_udelay(1);

  for (i = 0; i < 4; i++)
    {
      sr1 = SPI_REG32(LS_SPI_IO_SR1);
      if (sr1 & LS_SPI_SR1_RXE)
        {
          break;
        }

      (void)(uint8_t)SPI_REG32(LS_SPI_IO_DR);
    }

  SPI_REG32(LS_SPI_IO_CR3) = 0;
  SPI_REG32(LS_SPI_IO_DR) = tx;

  val = SPI_REG32(LS_SPI_IO_CR1);
  val |= LS_SPI_CR1_CSTART;
  SPI_REG32(LS_SPI_IO_CR1) = val;

  for (i = 0; i < SPI_WAIT_TIMEOUT_US; i++)
    {
      sr1 = SPI_REG32(LS_SPI_IO_SR1);
      if (sr1 & LS_SPI_SR1_RXA)
        {
          if (rx != NULL)
            {
              *rx = (uint8_t)SPI_REG32(LS_SPI_IO_DR);
            }
          else
            {
              (void)(uint8_t)SPI_REG32(LS_SPI_IO_DR);
            }

          val = SPI_REG32(LS_SPI_IO_CR1);
          val &= ~(LS_SPI_CR1_CSTART | LS_SPI_CR1_AUTOSUS);
          SPI_REG32(LS_SPI_IO_CR1) = val;
          return 0;
        }

      up_udelay(1);
    }

  sr1 = SPI_REG32(LS_SPI_IO_SR1);
  if (!(sr1 & LS_SPI_SR1_RXE))
    {
      if (rx != NULL)
        {
          *rx = (uint8_t)SPI_REG32(LS_SPI_IO_DR);
        }
      else
        {
          (void)(uint8_t)SPI_REG32(LS_SPI_IO_DR);
        }

      val = SPI_REG32(LS_SPI_IO_CR1);
      val &= ~(LS_SPI_CR1_CSTART | LS_SPI_CR1_AUTOSUS);
      SPI_REG32(LS_SPI_IO_CR1) = val;
      return 0;
    }

  spi2_abort();
  return -1;
}

static int spi2_init(void)
{
  uint32_t brint;

  /* Enable SPI2/3 module clock gate */

  CFG5_REG |= (0x3u << 17);

  /* CFG3: master, full duplex, software CS mode */

  SPI_REG32(LS_SPI_IO_CFG3) = LS_SPI_CFG3_MSTR | LS_SPI_CFG3_DIE |
                               LS_SPI_CFG3_DOE | LS_SPI_CFG3_SSMODE_SW;

  /* CFG1: 8-bit frame, SPI mode 0 */

  SPI_REG32(LS_SPI_IO_CFG1) = LS_SPI_CFG1_DSIZE_8BIT;

  /* CFG2: baud rate divider */

  brint = SPI_APB_HZ / SPI_CLOCK_HZ;
  if (brint < 2)
    {
      brint = 2;
    }

  if (brint > 255)
    {
      brint = 255;
    }

  SPI_REG32(LS_SPI_IO_CFG2) = brint << LS_SPI_CFG2_BRINT_SHIFT;

  /* CR1: enable SPI */

  SPI_REG32(LS_SPI_IO_CR1) = LS_SPI_CR1_SPE;

  /* Deselect all CS */

  gpio_write(g_fd_flash_cs, true);
  gpio_write(g_fd_adc_cs, true);
  up_udelay(10);

  return OK;
}

/****************************************************************************
 * Private Functions - GPIO Helpers
 ****************************************************************************/

static int gpio_open_output(int pin)
{
  int ret;
  char path[32];
  int fd;

  ret = pinctrl_set_gpio_function(pin);
  if (ret < 0)
    {
      printf("[SPIFLASH] ERROR: pinctrl GPIO%d: %d\n", pin, ret);
      return ret;
    }

  snprintf(path, sizeof(path), "/dev/gpio%d", pin);
  fd = open(path, O_RDWR);
  if (fd < 0)
    {
      printf("[SPIFLASH] ERROR: open %s: %d\n", path, errno);
      return -errno;
    }

  ret = ioctl(fd, GPIOC_SETPINTYPE, (unsigned long)GPIO_OUTPUT_PIN);
  if (ret < 0)
    {
      printf("[SPIFLASH] ERROR: set output GPIO%d: %d\n", pin, errno);
      close(fd);
      return -errno;
    }

  ioctl(fd, GPIOC_WRITE, (unsigned long)true);  /* default high */
  return fd;
}

static int gpio_open_input(int pin)
{
  int ret;
  char path[32];
  int fd;

  ret = pinctrl_set_gpio_function(pin);
  if (ret < 0)
    {
      printf("[SPIFLASH] ERROR: pinctrl GPIO%d: %d\n", pin, ret);
      return ret;
    }

  snprintf(path, sizeof(path), "/dev/gpio%d", pin);
  fd = open(path, O_RDWR);
  if (fd < 0)
    {
      printf("[SPIFLASH] ERROR: open %s: %d\n", path, errno);
      return -errno;
    }

  ret = ioctl(fd, GPIOC_SETPINTYPE, (unsigned long)GPIO_INPUT_PIN);
  if (ret < 0)
    {
      printf("[SPIFLASH] ERROR: set input GPIO%d: %d\n", pin, errno);
      close(fd);
      return -errno;
    }

  return fd;
}

static bool gpio_read(int fd)
{
  bool value = true;
  ioctl(fd, GPIOC_READ, (unsigned long)(uintptr_t)&value);
  return value;
}

static void gpio_write(int fd, bool value)
{
  ioctl(fd, GPIOC_WRITE, (unsigned long)value);
}

static int key_scan(int fd, bool *last)
{
  bool value = gpio_read(fd);

  if (!value && *last)
    {
      up_mdelay(KEY_DEBOUNCE_MS);
      value = gpio_read(fd);
      if (!value)
        {
          *last = value;
          return 1;
        }
    }

  *last = value;
  return 0;
}

/****************************************************************************
 * Private Functions - SPI Flash (CS on GPIO85)
 *
 * NOTE: Always call spi2_bus_reset() before flash operations to ensure
 *       clean bus state after ADC operations on the shared SPI2 bus.
 ****************************************************************************/

static void flash_cs_select(void)
{
  gpio_write(g_fd_adc_cs, true);     /* ensure ADC deselected first */
  up_udelay(1);
  gpio_write(g_fd_flash_cs, false);  /* select flash */
  up_udelay(1);
}

static void flash_cs_deselect(void)
{
  gpio_write(g_fd_flash_cs, true);   /* deselect flash */
  up_udelay(1);
}

static uint8_t flash_xfer(uint8_t tx)
{
  uint8_t rx = 0;
  spi2_xfer_byte(tx, &rx);
  return rx;
}

static void flash_read_jedec_id(uint8_t id[3])
{
  spi2_bus_reset();
  flash_cs_select();
  flash_xfer(SPIFLASH_CMD_READ_JEDEC_ID);
  id[0] = flash_xfer(0xff);
  id[1] = flash_xfer(0xff);
  id[2] = flash_xfer(0xff);
  flash_cs_deselect();
}

static int flash_id_valid(const uint8_t id[3])
{
  if ((id[0] == 0x00 && id[1] == 0x00 && id[2] == 0x00) ||
      (id[0] == 0xff && id[1] == 0xff && id[2] == 0xff))
    {
      return 0;
    }

  return 1;
}

static uint8_t flash_read_status(void)
{
  uint8_t status;

  flash_cs_select();
  flash_xfer(SPIFLASH_CMD_READ_STATUS);
  status = flash_xfer(0xff);
  flash_cs_deselect();

  return status;
}

static void flash_write_enable(void)
{
  flash_cs_select();
  flash_xfer(SPIFLASH_CMD_WRITE_ENABLE);
  flash_cs_deselect();
  up_udelay(1);
}

static int flash_wait_ready(FAR const char *op)
{
  uint8_t status = 0xff;
  int i;

  for (i = 0; i < 500; i++)
    {
      status = flash_read_status();
      if ((status & SPIFLASH_STATUS_WIP) == 0)
        {
          return OK;
        }

      up_mdelay(10);
    }

  printf("[SPIFLASH] %s timeout, status=0x%02x\n", op, status);
  return -ETIMEDOUT;
}

static int flash_sector_erase(uint32_t addr)
{
  spi2_bus_reset();
  flash_write_enable();

  flash_cs_select();
  flash_xfer(SPIFLASH_CMD_SECTOR_ERASE_4K);
  flash_xfer((uint8_t)(addr >> 16));
  flash_xfer((uint8_t)(addr >> 8));
  flash_xfer((uint8_t)addr);
  flash_cs_deselect();

  return flash_wait_ready("erase");
}

static int flash_page_program(uint32_t addr, FAR const uint8_t *data,
                              uint32_t len)
{
  uint32_t i;

  spi2_bus_reset();
  flash_write_enable();

  flash_cs_select();
  flash_xfer(SPIFLASH_CMD_PAGE_PROGRAM);
  flash_xfer((uint8_t)(addr >> 16));
  flash_xfer((uint8_t)(addr >> 8));
  flash_xfer((uint8_t)addr);

  for (i = 0; i < len; i++)
    {
      flash_xfer(data[i]);
    }

  flash_cs_deselect();

  return flash_wait_ready("program");
}

static void flash_read_data(uint32_t addr, FAR uint8_t *data, uint32_t len)
{
  uint32_t i;

  spi2_bus_reset();
  flash_cs_select();
  flash_xfer(SPIFLASH_CMD_READ_DATA);
  flash_xfer((uint8_t)(addr >> 16));
  flash_xfer((uint8_t)(addr >> 8));
  flash_xfer((uint8_t)addr);

  for (i = 0; i < len; i++)
    {
      data[i] = flash_xfer(0xff);
    }

  flash_cs_deselect();
}

static uint32_t flash_capacity_bytes(const uint8_t id[3])
{
  if (id[2] < 16 || id[2] > 30)
    {
      return 0;
    }

  return (uint32_t)(1UL << id[2]);
}

/****************************************************************************
 * Private Functions - MCP3204 ADC (CS on GPIO67)
 *
 * NOTE: Always deselect flash CS before ADC operations.
 ****************************************************************************/

static void adc_cs_select(void)
{
  gpio_write(g_fd_flash_cs, true);  /* ensure flash deselected first */
  up_udelay(1);
  gpio_write(g_fd_adc_cs, false);   /* select ADC */
  up_udelay(1);
}

static void adc_cs_deselect(void)
{
  gpio_write(g_fd_adc_cs, true);    /* deselect ADC */
  up_udelay(1);
}

static int mcp3204_read_raw(uint8_t channel, uint16_t *raw)
{
  uint8_t rx_hi = 0;
  uint8_t rx_lo = 0;
  int ret;

  /* Reset bus before ADC to ensure clean state */

  spi2_bus_reset();

  adc_cs_select();

  ret = spi2_xfer_byte(0x06, NULL);
  if (ret != 0)
    {
      adc_cs_deselect();
      return -1;
    }

  ret = spi2_xfer_byte((uint8_t)(channel << 6), &rx_hi);
  if (ret != 0)
    {
      adc_cs_deselect();
      return -1;
    }

  ret = spi2_xfer_byte(0x00, &rx_lo);
  if (ret != 0)
    {
      adc_cs_deselect();
      return -1;
    }

  adc_cs_deselect();

  /* Reject 0xff - MISO stuck high, no valid data */

  if (rx_hi == 0xff || rx_lo == 0xff)
    {
      return -1;
    }

  *raw = (uint16_t)((((uint16_t)rx_hi & 0x0fU) << 8) | rx_lo);
  return 0;
}

static int mcp3204_read_average(uint8_t channel, uint16_t *raw)
{
  uint32_t sum = 0;
  uint16_t value = 0;
  int ret;
  int i;
  int valid = 0;

  for (i = 0; i < MCP3204_SAMPLE_COUNT * 8; i++)
    {
      ret = mcp3204_read_raw(channel, &value);
      if (ret != 0)
        {
          up_mdelay(5);
          continue;
        }

      sum += value;
      valid++;
      if (valid >= MCP3204_SAMPLE_COUNT)
        {
          break;
        }

      up_mdelay(5);
    }

  if (valid == 0)
    {
      return -1;
    }

  *raw = (uint16_t)((sum + (valid / 2)) / valid);
  return 0;
}

static uint32_t mcp3204_raw_to_mv(uint16_t raw)
{
  return ((uint32_t)raw * MCP3204_VREF_MV + (MCP3204_ADC_MAX / 2)) /
         MCP3204_ADC_MAX;
}

/****************************************************************************
 * Private Functions - Flash Data Operations
 ****************************************************************************/

static void spiflash_print_stored_data(uint32_t base_addr)
{
  uint8_t magic;
  uint8_t count;
  uint8_t buf[2];
  uint16_t raw;
  uint32_t mv;
  int i;

  printf("[SPIFLASH] ---- Stored ADC Data in Flash ----\n");

  flash_read_data(base_addr + FLASH_MAGIC_ADDR, &magic, 1);
  printf("[SPIFLASH] Magic: 0x%02X (%s)\n",
         magic, (magic == FLASH_MAGIC_VALUE) ? "valid" : "invalid/empty");

  if (magic != FLASH_MAGIC_VALUE)
    {
      printf("[SPIFLASH] No valid data stored yet\n");
      printf("[SPIFLASH] ---- End ----\n\n");
      return;
    }

  flash_read_data(base_addr + FLASH_COUNT_ADDR, &count, 1);
  printf("[SPIFLASH] Stored readings: %u\n", count);

  if (count > FLASH_MAX_READINGS)
    {
      count = FLASH_MAX_READINGS;
    }

  for (i = 0; i < count; i++)
    {
      flash_read_data(base_addr + FLASH_DATA_ADDR + i * 2, buf, 2);
      raw = ((uint16_t)buf[0] << 8) | buf[1];
      mv = mcp3204_raw_to_mv(raw);
      printf("[SPIFLASH]   [%d] raw=%4u  voltage=%u.%03u V\n",
             i, raw, mv / 1000, mv % 1000);
    }

  printf("[SPIFLASH] ---- End ----\n\n");
}

static int spiflash_save_readings(uint32_t base_addr,
                                  const uint16_t *readings, int count)
{
  uint8_t buf[FLASH_MAX_READINGS * 2];
  uint8_t verify_buf[2];
  uint16_t stored;
  uint8_t count_u8;
  int i;
  int ret;

  if (count > FLASH_MAX_READINGS)
    {
      count = FLASH_MAX_READINGS;
    }

  count_u8 = (uint8_t)count;

  /* Pack readings into byte array (big-endian uint16_t) */

  for (i = 0; i < count; i++)
    {
      buf[i * 2]     = (uint8_t)(readings[i] >> 8);
      buf[i * 2 + 1] = (uint8_t)(readings[i] & 0xff);
    }

  /* Erase sector first */

  printf("[SPIFLASH] Erasing sector 0x%06X...\n",
         (unsigned int)(base_addr & ~(SPIFLASH_SECTOR_SIZE - 1)));
  ret = flash_sector_erase(base_addr & ~(SPIFLASH_SECTOR_SIZE - 1));
  if (ret < 0)
    {
      printf("[SPIFLASH] ERROR: erase failed: %d\n", ret);
      return ret;
    }

  /* Small delay after erase */

  up_mdelay(50);

  /* Write count */

  ret = flash_page_program(base_addr + FLASH_COUNT_ADDR, &count_u8, 1);
  if (ret < 0)
    {
      printf("[SPIFLASH] ERROR: write count: %d\n", ret);
      return ret;
    }

  /* Write data */

  ret = flash_page_program(base_addr + FLASH_DATA_ADDR, buf, count * 2);
  if (ret < 0)
    {
      printf("[SPIFLASH] ERROR: write data: %d\n", ret);
      return ret;
    }

  /* Write magic last (signals data is valid) */

  buf[0] = FLASH_MAGIC_VALUE;
  ret = flash_page_program(base_addr + FLASH_MAGIC_ADDR, buf, 1);
  if (ret < 0)
    {
      printf("[SPIFLASH] ERROR: write magic: %d\n", ret);
      return ret;
    }

  /* Verify */

  for (i = 0; i < count; i++)
    {
      flash_read_data(base_addr + FLASH_DATA_ADDR + i * 2, verify_buf, 2);
      stored = ((uint16_t)verify_buf[0] << 8) | verify_buf[1];
      if (stored != readings[i])
        {
          printf("[SPIFLASH] ERROR: verify[%d] mismatch: "
                 "expected %u, got %u\n", i, readings[i], stored);
          return -EIO;
        }
    }

  printf("[SPIFLASH] Saved and verified %d readings\n", count);
  return OK;
}

/****************************************************************************
 * Private Functions - Read ADC and Save
 ****************************************************************************/

static int read_adc_and_save(uint32_t flash_addr)
{
  uint16_t readings[FLASH_MAX_READINGS];
  uint16_t raw;
  uint32_t mv;
  int ret;
  int i;

  printf("\n[SPIFLASH] === KEY1 pressed: reading ADC CH%d x%d ===\n",
         MCP3204_CHANNEL, FLASH_MAX_READINGS);

  /* Read ADC 5 times */

  for (i = 0; i < FLASH_MAX_READINGS; i++)
    {
      usleep(300000);  /* 300ms between readings */

      ret = mcp3204_read_average(MCP3204_CHANNEL, &raw);
      if (ret < 0)
        {
          printf("[SPIFLASH]   [%d] ADC read failed: %d\n", i, ret);
          readings[i] = 0;
        }
      else
        {
          readings[i] = raw;
          mv = mcp3204_raw_to_mv(raw);
          printf("[SPIFLASH]   [%d] CH%d raw=%4u  voltage=%u.%03u V\n",
                 i, MCP3204_CHANNEL, raw, mv / 1000, mv % 1000);
        }
    }

  /* Ensure bus is clean before flash operations */

  spi2_bus_reset();
  up_mdelay(10);

  /* Save to SPI Flash */

  printf("[SPIFLASH] Saving readings to SPI Flash...\n");
  ret = spiflash_save_readings(flash_addr, readings, FLASH_MAX_READINGS);
  if (ret < 0)
    {
      printf("[SPIFLASH] Save failed!\n");
      return ret;
    }

  /* Read back and print */

  printf("[SPIFLASH] Verifying flash contents:\n");
  spiflash_print_stored_data(flash_addr);

  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int test_spiflash(void)
{
  uint8_t id[3] = {0};
  uint32_t capacity;
  uint32_t sector_addr;
  uint32_t flash_addr;
  bool key1_last;
  bool key2_last;
  int ret;

  printf("[SPIFLASH] === SPI Flash + ADC Test ===\n");
  printf("[SPIFLASH] SPI2 bus: SCK=GPIO64 MISO=GPIO65 MOSI=GPIO66\n");
  printf("[SPIFLASH] MCP3204 ADC CS=GPIO%d (CH%d)\n",
         ADC_CS_PIN, MCP3204_CHANNEL);
  printf("[SPIFLASH] SPI Flash CS=GPIO%d\n", FLASH_CS_PIN);
  printf("[SPIFLASH] KEY1=GPIO%d: read ADC x5, save to flash\n", KEY1_GPIO);
  printf("[SPIFLASH] KEY2=GPIO%d: exit\n\n", KEY2_GPIO);

  /* Initialize GPIO pins */

  g_fd_flash_cs = gpio_open_output(FLASH_CS_PIN);
  if (g_fd_flash_cs < 0)
    {
      return g_fd_flash_cs;
    }

  g_fd_adc_cs = gpio_open_output(ADC_CS_PIN);
  if (g_fd_adc_cs < 0)
    {
      close(g_fd_flash_cs);
      return g_fd_adc_cs;
    }

  g_fd_key1 = gpio_open_input(KEY1_GPIO);
  if (g_fd_key1 < 0)
    {
      close(g_fd_adc_cs);
      close(g_fd_flash_cs);
      return g_fd_key1;
    }

  g_fd_key2 = gpio_open_input(KEY2_GPIO);
  if (g_fd_key2 < 0)
    {
      close(g_fd_key1);
      close(g_fd_adc_cs);
      close(g_fd_flash_cs);
      return g_fd_key2;
    }

  printf("[SPIFLASH] GPIO initialized: FL_CS=GPIO%d ADC_CS=GPIO%d\n",
         FLASH_CS_PIN, ADC_CS_PIN);
  printf("[SPIFLASH] GPIO initialized: KEY1=GPIO%d KEY2=GPIO%d\n",
         KEY1_GPIO, KEY2_GPIO);

  /* Initialize SPI2 controller */

  ret = spi2_init();
  if (ret < 0)
    {
      printf("[SPIFLASH] ERROR: SPI2 init failed: %d\n", ret);
      goto cleanup;
    }

  printf("[SPIFLASH] SPI2 initialized (1MHz, mode 0, 8-bit)\n");
  up_mdelay(20);

  /* Reset bus and detect SPI Flash */

  spi2_bus_reset();
  up_mdelay(10);

  flash_read_jedec_id(id);
  printf("[SPIFLASH] Flash JEDEC ID: %02X %02X %02X\n",
         id[0], id[1], id[2]);

  if (!flash_id_valid(id))
    {
      printf("[SPIFLASH] ERROR: No valid SPI Flash detected!\n");
      printf("[SPIFLASH] Check wiring and CS pin mapping.\n");
      ret = -ENODEV;
      goto cleanup;
    }

  capacity = flash_capacity_bytes(id);
  if (capacity >= SPIFLASH_SECTOR_SIZE * 2)
    {
      sector_addr = capacity - SPIFLASH_SECTOR_SIZE;
    }
  else
    {
      sector_addr = 0;
    }

  flash_addr = sector_addr + SPIFLASH_TEST_OFFSET;

  if (capacity != 0)
    {
      printf("[SPIFLASH] Flash capacity: %u bytes (%u KB)\n",
             capacity, capacity / 1024);
    }

  printf("[SPIFLASH] Flash status: 0x%02X\n", flash_read_status());
  printf("[SPIFLASH] Data sector: 0x%06X, data addr: 0x%06X\n\n",
         (unsigned int)sector_addr, (unsigned int)flash_addr);

  /* Read and print current flash contents */

  printf("[SPIFLASH] Reading current flash contents...\n");
  spiflash_print_stored_data(flash_addr);

  /* Initialize key states */

  key1_last = gpio_read(g_fd_key1);
  key2_last = gpio_read(g_fd_key2);
  printf("[SPIFLASH] KEY1(GPIO%d) ready, waiting for press...\n", KEY1_GPIO);
  printf("[SPIFLASH] KEY2(GPIO%d) ready, press to exit\n\n", KEY2_GPIO);

  /* Main loop */

  while (1)
    {
      if (key_scan(g_fd_key1, &key1_last))
        {
          ret = read_adc_and_save(flash_addr);
          if (ret < 0)
            {
              printf("[SPIFLASH] read_adc_and_save failed: %d\n", ret);
            }

          printf("\n[SPIFLASH] Waiting for next KEY1 press...\n\n");
        }

      if (key_scan(g_fd_key2, &key2_last))
        {
          printf("\n[SPIFLASH] KEY2 pressed, exiting...\n");
          break;
        }

      up_mdelay(KEY_SCAN_DELAY_MS);
    }

  ret = OK;

cleanup:
  /* Ensure both CS are deselected before exit */

  spi2_bus_reset();
  close(g_fd_key2);
  close(g_fd_key1);
  close(g_fd_adc_cs);
  close(g_fd_flash_cs);

  printf("[SPIFLASH] Test complete.\n");
  return ret;
}

