236	static uint8_t LsHwSpiXferByte(uint8_t tx)
237	{
238	    volatile unsigned char *base = (volatile unsigned char *)LS_SPI2_BASE;
239	    uint32_t val;
240	
241	    /* 使能 SPI 控制器 */
242	    val = readl(base + LS_SPI_IO_CR1);
243	    val |= LS_SPI_CR1_SPE;
244	    writel(val, base + LS_SPI_IO_CR1);
245	
246	    /* 挂起可能仍在进行的传输：清 CSTART/AUTOSUS，
247	     * 保证每次传输都有干净的 0->1 上升沿 */
248	    val = readl(base + LS_SPI_IO_CR1);
249	    val &= ~(LS_SPI_CR1_CSTART | LS_SPI_CR1_AUTOSUS);
250	    writel(val, base + LS_SPI_IO_CR1);
251	
252	    /* 清残留状态标志位（W1C） */
253	    writel(LS_SPI_SR1_W1C_FLAGS, base + LS_SPI_IO_SR1);
254	
255	    /* CR3 TSIZE: 单次传输帧数 = TSIZE+1 = 1 帧 */
256	    writel(0, base + LS_SPI_IO_CR3);
257	
258	    /* 等待 TXFIFO 可写 */
259	    if (LsHwSpiWaitFlag(LS_SPI_SR1_TXA, 0) != 0) {
260	        printf(" LOONG_HAT SPI FLASH TXA timeout\r\n");
261	        LsHwSpiAbort();
262	        return 0xFF;
263	    }
264	
265	    /* 写入待发送字节 */
266	    writeb(tx, base + LS_SPI_IO_DR);
267	
268	    /* 启动一帧传输：只置 CSTART，不置 AUTOSUS。
269	     * 手册 10.2.1 描述 AUTOSUS=1 是"传完当前传输后重新载入 TSIZE 继续传输"，
270	     * 会让 EOT(bit15) 永不置位而超时；AUTOSUS=0 则传完即挂起并置 EOT。 */
271	    val = readl(base + LS_SPI_IO_CR1);
272	    val |= LS_SPI_CR1_CSTART;
273	    writel(val, base + LS_SPI_IO_CR1);
274	
275	    /* 等待传输结束 */
276	    if (LsHwSpiWaitFlag(LS_SPI_SR1_EOT, 1) != 0) {
277	        printf(" LOONG_HAT SPI FLASH EOT timeout: SR1=0x%08x CR1=0x%08x CR3=0x%08x CR4=0x%08x\r\n",
278	            readl(base + LS_SPI_IO_SR1), readl(base + LS_SPI_IO_CR1),
279	            readl(base + LS_SPI_IO_CR3), readl(base + LS_SPI_IO_CR4));
280	        LsHwSpiAbort();
281	        return 0xFF;
282	    }
283	
284	    /* 等待 RXFIFO 有数据 */
285	    if (LsHwSpiWaitFlag(LS_SPI_SR1_RXA, 0) != 0) {
286	        printf(" LOONG_HAT SPI FLASH RXA timeout: SR1=0x%08x\r\n", readl(base + LS_SPI_IO_SR1));
287	        LsHwSpiAbort();
288	        return 0xFF;
289	    }

