93	int spi_init(void)
94	{
95	  uint32_t brint;
96	  int ret;
97	
98	  /* CS GPIO 初始化 */
99	
100	  ret = pinctrl_set_gpio_function(CS_PIN);
101	  if (ret < 0) return ret;
102	
103	  g_fd_cs = open("/dev/gpio" __XSTRING(CS_PIN), O_RDWR);
104	  if (g_fd_cs < 0) return -errno;
105	
106	  ret = ioctl(g_fd_cs, GPIOC_SETPINTYPE, (unsigned long)GPIO_OUTPUT_PIN);
107	  if (ret < 0) return -errno;
108	
109	  ioctl(g_fd_cs, GPIOC_WRITE, 1);  /* CS 高（空闲） */
110	
111	  /* 使能 SPI2/3 时钟门控 */
112	  CFG5_REG |= (0x3u << 17);
113	
114	  /* CFG3: 主模式、全双工、软件 CS */
115	
116	  SPI_REG32(SPI_IO_CFG3) = SPI_CFG3_MSTR | SPI_CFG3_DIE |
117	                            SPI_CFG3_DOE | SPI_CFG3_SSMODE_SW;
118	
119	  /* CFG1: 8-bit 帧 */
120	
121	  SPI_REG32(SPI_IO_CFG1) = SPI_CFG1_DSIZE_8BIT;
122	
123	  /* CFG2: 波特率分频 */
124	
125	  brint = APB_HZ / SPI_CLOCK_HZ;
126	  if (brint < 2) brint = 2;
127	  if (brint > 255) brint = 255;
128	  SPI_REG32(SPI_IO_CFG2) = brint << 8;
129	
130	  /* CR1: 使能 SPI */
131	
132	  SPI_REG32(SPI_IO_CR1) = SPI_CR1_SPE;
133	
134	  printf("[SPI] Init done, base=0x%lx, sclk=%lu Hz\n",
135	         (unsigned long)SPI_BASE, (unsigned long)SPI_CLOCK_HZ);
136	  return 0;
137	}
