147	 *   rx - 接收字节指针（可为 NULL）
148	 *
149	 * Returned Value:
150	 *   0 on success, -1 on timeout.
151	 ****************************************************************************/
152	
153	int spi_xfer_byte(uint8_t tx, uint8_t *rx)
154	{
155	  uint32_t val;
156	  uint32_t sr1;
157	  uint32_t i;
158	
159	  /* 1. 使能 SPI */
160	
161	  val = SPI_REG32(SPI_IO_CR1);
162	  val |= SPI_CR1_SPE;
163	  SPI_REG32(SPI_IO_CR1) = val;
164	
165	  /* 2. 终止待处理传输 */
166	
167	  val = SPI_REG32(SPI_IO_CR1);
168	  val &= ~(SPI_CR1_CSTART | SPI_CR1_AUTOSUS);
169	  SPI_REG32(SPI_IO_CR1) = val;
170	
171	  /* 3. 清空 FIFO 和状态标志 */
172	
173	  SPI_REG32(SPI_IO_CR4) = 0;
174	  SPI_REG32(SPI_IO_CR3) = 0;
175	  up_udelay(5);
176	  SPI_REG32(SPI_IO_SR1) = SPI_SR1_W1C_FLAGS;
177	  up_udelay(1);
178	
179	  /* 4. 排空 RX FIFO */
180	
181	  for (i = 0; i < 4; i++)
182	    {
183	      sr1 = SPI_REG32(SPI_IO_SR1);
184	      if (sr1 & SPI_SR1_RXE) break;
185	      (void)(uint8_t)SPI_REG32(SPI_IO_DR);
186	    }
187	
188	  /* 5. 写入待发送数据 */
189	
190	  SPI_REG32(SPI_IO_CR3) = 0;
191	  SPI_REG32(SPI_IO_DR) = tx;
192	
193	  /* 6. 启动传输 */
194	
195	  val = SPI_REG32(SPI_IO_CR1);
196	  val |= SPI_CR1_CSTART;
197	  SPI_REG32(SPI_IO_CR1) = val;
198	
199	  /* 7. 等待 RX 数据就绪 */
200	
201	  for (i = 0; i < SPI_WAIT_TIMEOUT_US; i++)
202	    {
203	      sr1 = SPI_REG32(SPI_IO_SR1);
204	      if (sr1 & SPI_SR1_RXA)
205	        {
206	          if (rx) *rx = (uint8_t)SPI_REG32(SPI_IO_DR);
207	          val = SPI_REG32(SPI_IO_CR1);
208	          val &= ~(SPI_CR1_CSTART | SPI_CR1_AUTOSUS);
209	          SPI_REG32(SPI_IO_CR1) = val;
210	          return 0;
211	        }
212	
213	      up_udelay(1);
214	    }
215	
216	  /* 8. 超时 fallback */
217	
218	  sr1 = SPI_REG32(SPI_IO_SR1);
219	  if (!(sr1 & SPI_SR1_RXE))
220	    {
221	      if (rx) *rx = (uint8_t)SPI_REG32(SPI_IO_DR);
222	      val = SPI_REG32(SPI_IO_CR1);
223	      val &= ~(SPI_CR1_CSTART | SPI_CR1_AUTOSUS);
224	      SPI_REG32(SPI_IO_CR1) = val;
225	      return 0;
226	    }
227	
228	  /* Abort */
229	
230	  val = SPI_REG32(SPI_IO_CR1);
231	  val &= ~(SPI_CR1_CSTART | SPI_CR1_AUTOSUS);
232	  SPI_REG32(SPI_IO_CR1) = val;
233	  SPI_REG32(SPI_IO_CR4) = 0;
234	  SPI_REG32(SPI_IO_CR3) = 0;
235	  up_udelay(10);
236	  SPI_REG32(SPI_IO_SR1) = SPI_SR1_W1C_FLAGS;
237	  for (i = 0; i < 4; i++)
238	    {
239	      if (SPI_REG32(SPI_IO_SR1) & SPI_SR1_RXE) break;
240	      (void)(uint8_t)SPI_REG32(SPI_IO_DR);
241	    }
242	
243	  ioctl(g_fd_cs, GPIOC_WRITE, 1);
244	  up_udelay(1);
245	  return -1;
246	}
247	
248	/****************************************************************************
249	 * Name: spi_cs_low / spi_cs_high
250	 *
251	 * Description:
252	 *   软件控制片选信号。
253	 ****************************************************************************/
254	
255	void spi_cs_low(void)
256	{
257	  ioctl(g_fd_cs, GPIOC_WRITE, 0);
258	  up_udelay(1);
259	}
260	
261	void spi_cs_high(void)
262	{
263	  ioctl(g_fd_cs, GPIOC_WRITE, 1);
264	  up_udelay(1);
265	}
266	
267	/****************************************************************************
268	 * Name: spi_deinit
269	 ****************************************************************************/
270	
271	void spi_deinit(void)
272	{
273	  if (g_fd_cs >= 0)
274	    {
275	      spi_cs_high();
276	      close(g_fd_cs);
277	      g_fd_cs = -1;
278	    }
279	}
