{
  uint32_t val;
  uint32_t sr1;
  uint32_t i;

  /* 1. 使能 SPI */

  val = SPI_REG32(SPI_IO_CR1);
  val |= SPI_CR1_SPE;
  SPI_REG32(SPI_IO_CR1) = val;

  /* 2. 终止待处理传输 */

  val = SPI_REG32(SPI_IO_CR1);
  val &= ~(SPI_CR1_CSTART | SPI_CR1_AUTOSUS);
  SPI_REG32(SPI_IO_CR1) = val;

  /* 3. 清空 FIFO 和状态标志 */

  SPI_REG32(SPI_IO_CR4) = 0;
  SPI_REG32(SPI_IO_CR3) = 0;
  up_udelay(5);
  SPI_REG32(SPI_IO_SR1) = SPI_SR1_W1C_FLAGS;
  up_udelay(1);

  /* 4. 排空 RX FIFO */

  for (i = 0; i < 4; i++)
    {
      sr1 = SPI_REG32(SPI_IO_SR1);
      if (sr1 & SPI_SR1_RXE) break;
      (void)(uint8_t)SPI_REG32(SPI_IO_DR);
    }

  /* 5. 写入待发送数据 */

  SPI_REG32(SPI_IO_CR3) = 0;
  SPI_REG32(SPI_IO_DR) = tx;

  /* 6. 启动传输 */

  val = SPI_REG32(SPI_IO_CR1);
  val |= SPI_CR1_CSTART;
  SPI_REG32(SPI_IO_CR1) = val;

  /* 7. 等待 RX 数据就绪 */

  for (i = 0; i < SPI_WAIT_TIMEOUT_US; i++)
    {
      sr1 = SPI_REG32(SPI_IO_SR1);
      if (sr1 & SPI_SR1_RXA)
        {
          if (rx) *rx = (uint8_t)SPI_REG32(SPI_IO_DR);
          val = SPI_REG32(SPI_IO_CR1);
          val &= ~(SPI_CR1_CSTART | SPI_CR1_AUTOSUS);
          SPI_REG32(SPI_IO_CR1) = val;
          return 0;
        }

      up_udelay(1);
    }

  /* 8. 超时 fallback */

  sr1 = SPI_REG32(SPI_IO_SR1);
  if (!(sr1 & SPI_SR1_RXE))
    {
      if (rx) *rx = (uint8_t)SPI_REG32(SPI_IO_DR);
      val = SPI_REG32(SPI_IO_CR1);
      val &= ~(SPI_CR1_CSTART | SPI_CR1_AUTOSUS);
      SPI_REG32(SPI_IO_CR1) = val;
      return 0;
    }

  /* Abort */

  val = SPI_REG32(SPI_IO_CR1);
  val &= ~(SPI_CR1_CSTART | SPI_CR1_AUTOSUS);
  SPI_REG32(SPI_IO_CR1) = val;
  SPI_REG32(SPI_IO_CR4) = 0;
  SPI_REG32(SPI_IO_CR3) = 0;
