      if (sr1 & SPI_SR1_EOT) break;
      up_udelay(1);
    }

  if (i >= SPI_WAIT_TIMEOUT_US) goto abort;

  /* 9. 清除 EOT */

  SPI_REG32(SPI_IO_SR1) = SPI_SR1_EOT;

  /* 10. 等待 RX FIFO 有数据 */

  for (i = 0; i < SPI_WAIT_TIMEOUT_US; i++)
