247	static int mcp3204_init(void)
248	{
249	  int ret;
250	  uint32_t brint;
251	
252	  printf("[ADC] MCP3204 hardware SPI2 init\n");
253	
254	  ret = pinctrl_set_gpio_function(MCP3204_CS_PIN);
255	  if (ret < 0)
256	    {
257	      printf("[ADC] ERROR: pinctrl CS GPIO%d: %d\n", MCP3204_CS_PIN, ret);
258	      return ret;
259	    }
260	
261	  g_fd_cs = open("/dev/gpio67", O_RDWR);
262	  if (g_fd_cs < 0)
263	    {
264	      printf("[ADC] ERROR: open CS GPIO%d: %d\n", MCP3204_CS_PIN, errno);
265	      return -errno;
266	    }
267	
268	  ret = ioctl(g_fd_cs, GPIOC_SETPINTYPE, (unsigned long)GPIO_OUTPUT_PIN);
269	  if (ret < 0)
270	    {
271	      printf("[ADC] ERROR: CS set output: %d\n", errno);
272	      close(g_fd_cs);
273	      g_fd_cs = -1;
274	      return -errno;
275	    }
276	
277	  ioctl(g_fd_cs, GPIOC_WRITE, 1);
278	
279	  CFG5_REG |= (0x3u << 17);
280	
281	  SPI_REG32(LS_SPI_IO_CFG3) = LS_SPI_CFG3_MSTR | LS_SPI_CFG3_DIE |
282	                               LS_SPI_CFG3_DOE | LS_SPI_CFG3_SSMODE_SW;
283	  SPI_REG32(LS_SPI_IO_CFG1) = LS_SPI_CFG1_DSIZE_8BIT;
284	
285	  brint = SPI_APB_HZ / SPI_CLOCK_HZ;
286	  if (brint < 2) brint = 2;
287	  if (brint > 255) brint = 255;
288	  SPI_REG32(LS_SPI_IO_CFG2) = brint << LS_SPI_CFG2_BRINT_SHIFT;
289	
290	  SPI_REG32(LS_SPI_IO_CR1) = LS_SPI_CR1_SPE;
291	
292	  printf("[ADC] SPI2 init done, Vref=%u mV\n", MCP3204_VREF_MV);
293	  return 0;
294	}
