1	# SPI ADC 驱动设计文档（MCP3204 范例）
2	
3	## 1. 功能概述
4	
5	通过硬件 SPI 控制器读取 MCP3204 12 位 ADC 的模拟电压值。
6	
7	### MCP3204 特性
8	- 12 位 SAR ADC
9	- 4 通道单端输入（CH0~CH3）
10	- SPI 接口，最高 1.2MHz
11	- 参考电压 VREF 由外部提供
12	
13	## 2. 板级配置（必须先完成）
14	
15	### 2.1 引脚复用
16	
17	在 `nuttx/boards/loongarch/ls2k300/hummingbird-ls2k300/src/ls2k300_bringup.c` 的
18	`ls2k300_hardware_init()` 中添加：
19	
20	```c
21	/* SPI2: GPIO64/65/66 → MAIN_FUNC, GPIO67 → GPIO(软件CS) */
22	ls_pinmux_pin_setup(64, LS_PINMUX_MODE_AS_MAIN_FUNC);
23	ls_pinmux_pin_setup(65, LS_PINMUX_MODE_AS_MAIN_FUNC);
24	ls_pinmux_pin_setup(66, LS_PINMUX_MODE_AS_MAIN_FUNC);
25	ls_pinmux_pin_setup(67, LS_PINMUX_MODE_AS_GPIO);
26	```
27	
28	### 2.2 Kconfig 使能
29	
30	在 `nuttx/boards/loongarch/ls2k300/hummingbird-ls2k300/configs/nsh/defconfig` 中添加：
31	
32	```
33	CONFIG_LS2K300_SPI=y
34	CONFIG_LS2K300_SPIIO2=y
35	```
36	
37	## 3. SPI 时序要求
38	
39	### 3.1 SPI 模式
40	
41	MCP3204 使用 **SPI Mode 0**（CPOL=0, CPHA=0）：
42	- 空闲时 SCK 为低电平
43	- 数据在 SCK 上升沿采样
44	- 数据在 SCK 下降沿变化
45	
46	### 3.2 传输时序
47	
48	```
49	CS:  ‾‾‾\___________________________________/‾‾‾
50	SCK: ____|‾|_|‾|_|‾|_|‾|_|‾|_|‾|_|‾|_|‾|_|‾|____
51	MOSI:    |S|D|D|D|D|D|D|D|D|x|x|x|x|x|x|x|x|
52	MISO:    |x|N|D11|D10|D9|D8|D7|D6|D5|D4|D3|D2|D1|D0|x|x|
53	```
54	
55	### 3.3 命令字节格式
56	
57	| 字节 | 内容 | 说明 |
58	|------|------|------|
59	| Byte 1 | `0x06` | Start bit=1, Single-ended=1, D2=0 |
60	| Byte 2 | `channel << 6` | D2=0, D1/D0=通道号 |
61	| Byte 3 | `0x00` | 无关紧要，用于接收数据 |
62	
63	### 3.4 接收数据格式
64	
65	| 字节 | 位内容 |
66	|------|--------|
67	| Byte 1 响应 | `null, D11, D10, D9, D8, D7, D6, D5`（延迟 1 位） |
68	| Byte 2 响应 | `D5, D4, D3, D2, D1, D0, x, x` |
69	| Byte 3 响应 | 无效数据 |
70	
71	**注意**：硬件 SPI 存在 1 位流水线延迟，第一个字节的响应在第二个字节传输时才读出。
72	
73	## 4. 硬件 SPI 控制器配置
74	
75	### 4.1 初始化流程
76	
77	```c
78	/* Step 1: 使能 SPI 时钟门控 */
79	CFG5_REG |= (0x3u << 17);
80	
81	/* Step 2: 配置 CFG3 - 主模式、全双工、软件 CS */
82	SPI_REG32(CFG3_OFFSET) = MSTR | DIE | DOE | SSMODE_SW;
83	
84	/* Step 3: 配置 CFG1 - 8-bit 帧、SPI Mode 0 */
85	SPI_REG32(CFG1_OFFSET) = DSIZE_8BIT;
86	
87	/* Step 4: 配置 CFG2 - 波特率分频 */
88	uint32_t brint = APB_HZ / TARGET_CLOCK_HZ;
89	SPI_REG32(CFG2_OFFSET) = brint << BRINT_SHIFT;
90	
91	/* Step 5: 使能 SPI */
92	SPI_REG32(CR1_OFFSET) = SPE;
93	```
94	
95	### 4.2 单字节传输函数
96	
97	```c
98	static int spi_xfer_byte(uint8_t tx, uint8_t *rx)
99	{
100	  uint32_t val, sr1;
101	  uint32_t i;
102	
103	  /* 1. 使能 SPI */
104	  val = SPI_REG32(CR1_OFFSET);
105	  val |= SPE;
106	  SPI_REG32(CR1_OFFSET) = val;
107	
108	  /* 2. 终止挂起的传输 */
109	  val = SPI_REG32(CR1_OFFSET);
110	  val &= ~(CSTART | AUTOSUS);
111	  SPI_REG32(CR1_OFFSET) = val;
112	
113	  /* 3. 清空 FIFO */
114	  SPI_REG32(CR4_OFFSET) = 0;
115	  SPI_REG32(CR3_OFFSET) = 0;
116	  up_udelay(5);
117	
118	  /* 4. 清除状态标志 */
119	  SPI_REG32(SR1_OFFSET) = W1C_FLAGS;
120	  up_udelay(1);
121	
122	  /* 5. 排空 RXFIFO */
123	  for (i = 0; i < 4; i++)
124	    {
125	      sr1 = SPI_REG32(SR1_OFFSET);
126	      if (sr1 & RXE) break;
127	      (void)(uint8_t)SPI_REG32(DR_OFFSET);
128	    }
129	
130	  /* 6. 发送数据 */
131	  SPI_REG32(CR3_OFFSET) = 0;
132	  SPI_REG32(DR_OFFSET) = tx;
133	
134	  /* 7. 启动传输 */
135	  val = SPI_REG32(CR1_OFFSET);
136	  val |= CSTART;
137	  SPI_REG32(CR1_OFFSET) = val;
138	
139	  /* 8. 等待 RX 数据 */
140	  for (i = 0; i < TIMEOUT_US; i++)
141	    {
142	      sr1 = SPI_REG32(SR1_OFFSET);
143	      if (sr1 & RXA)
144	        {
145	          if (rx) *rx = (uint8_t)SPI_REG32(DR_OFFSET);
146	          else     (void)(uint8_t)SPI_REG32(DR_OFFSET);
147	
148	          val = SPI_REG32(CR1_OFFSET);
149	          val &= ~(CSTART | AUTOSUS);
150	          SPI_REG32(CR1_OFFSET) = val;
151	          return 0;
152	        }
153	      up_udelay(1);
154	    }
155	
156	  /* 9. 超时 fallback：尝试直接读 DR */
157	  sr1 = SPI_REG32(SR1_OFFSET);
158	  if (!(sr1 & RXE))
159	    {
160	      if (rx) *rx = (uint8_t)SPI_REG32(DR_OFFSET);
161	      else     (void)(uint8_t)SPI_REG32(DR_OFFSET);
162	
163	      val = SPI_REG32(CR1_OFFSET);
164	      val &= ~(CSTART | AUTOSUS);
165	      SPI_REG32(CR1_OFFSET) = val;
166	      return 0;
167	    }
168	
169	  /* 10. 失败：中止传输 */
170	  spi_abort();
171	  return -1;
172	}
173	```
174	
175	### 4.3 关键注意事项
176	
177	> ⚠️ **超时 fallback 必须保留**：SPI 控制器可能在 RXA 标志未置位时已有数据在 DR 中。
178	> 删除 fallback 会导致 SPI 通信完全失败（所有读取返回 0xff）。
179	
180	## 5. 片选（CS）控制
181	
182	使用 GPIO 软件控制 CS：
183	
184	```c
185	/* CS 拉低 - 开始传输 */
186	ioctl(cs_fd, GPIOC_WRITE, 0);
187	up_udelay(1);
188	
189	/* 执行 SPI 传输 */
190	spi_xfer_byte(tx1, NULL);
191	spi_xfer_byte(tx2, &rx_hi);
192	spi_xfer_byte(tx3, &rx_lo);
193	
194	/* CS 拉高 - 结束传输 */
195	ioctl(cs_fd, GPIOC_WRITE, 1);
196	up_udelay(1);
197	```
198	
199	## 6. MCP3204 读取完整流程
200	
201	```c
202	int mcp3204_read(uint8_t channel, uint16_t *raw)
203	{
204	  uint8_t rx_hi = 0, rx_lo = 0;
205	
206	  /* CS 低 */
207	  ioctl(cs_fd, GPIOC_WRITE, 0);
208	  up_udelay(1);
209	
210	  /* 发送 3 字节命令 */
211	  if (spi_xfer_byte(0x06, NULL) != 0 ||               /* Start + Single-ended */
212	      spi_xfer_byte((channel << 6), &rx_hi) != 0 ||   /* 通道号 */
213	      spi_xfer_byte(0x00, &rx_lo) != 0)               /* 接收数据 */
214	    {
215	      ioctl(cs_fd, GPIOC_WRITE, 1);
216	      return -1;
217	    }
218	
219	  /* CS 高 */
220	  ioctl(cs_fd, GPIOC_WRITE, 1);
221	  up_udelay(1);
222	
223	  /* 过滤无效数据 */
224	  if (rx_hi == 0xff || rx_lo == 0xff)
225	    return -1;
226	
227	  /* 提取 12 位 ADC 值 */
228	  *raw = ((uint16_t)(rx_hi & 0x0F) << 8) | rx_lo;
229	  return 0;
230	}
231	```
232	
233	## 7. 电压换算
234	
235	```c
236	uint32_t adc_to_voltage_mv(uint16_t raw, uint32_t vref_mv)
237	{
238	  return ((uint32_t)raw * vref_mv + (ADC_MAX / 2)) / ADC_MAX;
239	}
240	```
241	
242	> ⚠️ **使用整数运算**：LoongArch 默认无 FPU，禁止使用 float/double。
243	
244	## 8. 防误码与重试
245	
246	```c
247	int mcp3204_read_average(uint8_t channel, uint16_t *raw, int samples)
248	{
249	  uint32_t sum = 0;
250	  int valid = 0;
251	
252	  for (int i = 0; i < samples * 8; i++)  /* 最多重试 8 倍 */
253	    {
254	      uint16_t value;
255	      if (mcp3204_read(channel, &value) != 0)
256	        {
257	          up_mdelay(2);
258	          continue;  /* 跳过坏数据，继续采样 */
259	        }
260	
261	      sum += value;
262	      if (++valid >= samples)
263	        break;
264	
265	      up_mdelay(2);
266	    }
267	
268	  if (valid == 0) return -1;
269	
270	  *raw = (sum + valid / 2) / valid;
271	  return 0;
272	}
273	```
274	
275	## 9. 调试技巧
276	
277	1. **所有读取返回 0xff**：
278	   - 检查 SPI 时钟门控是否使能（CFG5）
279	   - 检查引脚复用是否配置为 SPI 功能
280	   - 确认 `spi_xfer_byte` 包含超时 fallback 代码
281	   - 确认 DR 寄存器使用了 8 位访问（SPI_REG8）
282	
283	2. **读数不随输入变化**：
284	   - 检查 CS 是否正确控制（GPIO 方向、电平）
285	   - 用示波器观察 SCK/MOSI/MISO 波形
286	
287	3. **读数偏差较大**：
288	   - 检查 VREF 电压是否稳定
289	   - 增加采样平均次数
290	   - 添加 0xff 过滤逻辑
291	
292	4. **编译报错 undefined reference**：
293	   - 检查头文件路径是否正确
294	   - 检查 ioctl 宏名（I2CIOC_TRANSFER vs I2C_TRANSFER）
295	   - 检查 defconfig 中对应的 CONFIG 是否使能
296	
297	5. **设备节点不存在（open 失败）**：
298	   - 检查 defconfig 中对应的 CONFIG 是否使能
299	   - 检查 bringup.c 中是否注册了该外设
300	   - 检查是否遗漏了 `CONFIG_I2C_DRIVER=y`（I2C 设备必须）
