1	/****************************************************************************
2	 * assets/spi_template.c
3	 *
4	 * 硬件 SPI 驱动模板 - SPI 读写接口封装
5	 *
6	 * Hummingbird 2K300 板 SPI2 引脚：
7	 *   - SPI2_CLK:  GPIO64 (MAIN_FUNC)
8	 *   - SPI2_MISO: GPIO65 (MAIN_FUNC)
9	 *   - SPI2_MOSI: GPIO66 (MAIN_FUNC)
10	 *   - CSN1:      GPIO67 (GPIO, 软件片选)
11	 *   - SPI2 基地址: 0x1610c000
12	 *   - APB 时钟: 200MHz
13	 *
14	 * 使用说明：
15	 *   1. 引脚复用在 ls2k300_bringup.c 中已配置
16	 *   2. CS_PIN 已设为 GPIO67
17	 *   3. 根据从设备要求调整 SPI 模式（CPOL/CPHA）
18	 ****************************************************************************/
19	
20	#include <nuttx/config.h>
21	#include <sys/ioctl.h>
22	#include <stdio.h>
23	#include <fcntl.h>
24	#include <unistd.h>
25	#include <stdint.h>
26	
27	#include <nuttx/arch.h>
28	#include <nuttx/ioexpander/gpio.h>
29	
30	/* Hummingbird 2K300 板 SPI2 配置 */
31	
32	#define SPI_BASE_PHYS       0x1610c000UL
33	#define SPI_BASE            (0x8000000000000000UL | SPI_BASE_PHYS)
34	#define CS_PIN              67               /* GPIO67 = MCP3204 软件片选 */
35	#define APB_HZ              (200UL * 1000000UL)
36	#define SPI_CLOCK_HZ        1000000UL        /* MCP3204 最大 1.2MHz */
37	
38	/* GENERAL_CFG5: SPI2/3 时钟门控寄存器 */
39	#define GENERAL_CFG5_ADDR   (0x8000000000000000UL | 0x16000114UL)
40	#define CFG5_REG            (*(volatile uint32_t *)GENERAL_CFG5_ADDR)
41	#define SPI_WAIT_TIMEOUT_US 10000U
42	
43	/* SPI2 寄存器偏移（LS2K300 通用） */
44	
45	#define SPI_IO_CR1          0x00
46	#define SPI_IO_CR3          0x08
47	#define SPI_IO_CR4          0x0c
48	#define SPI_IO_SR1          0x14
49	#define SPI_IO_CFG1         0x20
50	#define SPI_IO_CFG2         0x24
51	#define SPI_IO_CFG3         0x28
52	#define SPI_IO_DR           0x40
53	
54	/* CR1 位 */
55	
56	#define SPI_CR1_SPE         (1U << 0)
57	#define SPI_CR1_CSTART      (1U << 1)
58	#define SPI_CR1_AUTOSUS     (1U << 2)
59	
60	/* CFG1: 8-bit frame, Mode 0 */
61	
62	#define SPI_CFG1_DSIZE_8BIT (7U << 8)
63	
64	/* CFG3 */
65	
66	#define SPI_CFG3_MSTR       (1U << 0)
67	#define SPI_CFG3_DIE        (1U << 2)
68	#define SPI_CFG3_DOE        (1U << 3)
69	#define SPI_CFG3_SSMODE_SW  (1U << 8)
70	
71	/* SR1 */
72	
73	#define SPI_SR1_RXA         (1U << 0)
74	#define SPI_SR1_TXA         (1U << 1)
75	#define SPI_SR1_RXE         (1U << 4)
76	#define SPI_SR1_EOT         (1U << 15)
77	#define SPI_SR1_W1C_FLAGS   (SPI_SR1_EOT | (1U << 11) | \
78	                             (1U << 10) | (1U << 9) | (1U << 8))
79	
80	/* 寄存器访问（⚠️ DR 必须用 8 位访问，其他寄存器用 32 位） */
81	
82	#define SPI_REG32(off)  (*(volatile uint32_t *)(SPI_BASE + (off)))
83	#define SPI_REG8(off)   (*(volatile uint8_t *)(SPI_BASE + (off)))
84	
85	static int g_fd_cs = -1;
86	
87	/****************************************************************************
88	 * Name: spi_init
89	 *
90	 * Description:
91	 *   初始化 SPI 控制器和 CS GPIO。
92	 ****************************************************************************/
93	
94	int spi_init(void)
95	{
96	  uint32_t brint;
97	  int ret;
98	
99	  /* CS GPIO 初始化 */
100	
101	  ret = pinctrl_set_gpio_function(CS_PIN);
102	  if (ret < 0) return ret;
103	
104	  g_fd_cs = open("/dev/gpio" __XSTRING(CS_PIN), O_RDWR);
105	  if (g_fd_cs < 0) return -errno;
106	
107	  ret = ioctl(g_fd_cs, GPIOC_SETPINTYPE, (unsigned long)GPIO_OUTPUT_PIN);
108	  if (ret < 0) return -errno;
109	
110	  ioctl(g_fd_cs, GPIOC_WRITE, 1);  /* CS 高（空闲） */
111	
112	  /* 使能 SPI2/3 时钟门控 */
113	  CFG5_REG |= (0x3u << 17);
114	
115	  /* CFG3: 主模式、全双工、软件 CS */
116	
117	  SPI_REG32(SPI_IO_CFG3) = SPI_CFG3_MSTR | SPI_CFG3_DIE |
118	                            SPI_CFG3_DOE | SPI_CFG3_SSMODE_SW;
119	
120	  /* CFG1: 8-bit 帧 */
121	
122	  SPI_REG32(SPI_IO_CFG1) = SPI_CFG1_DSIZE_8BIT;
123	
124	  /* CFG2: 波特率分频 */
125	
126	  brint = APB_HZ / SPI_CLOCK_HZ;
127	  if (brint < 2) brint = 2;
128	  if (brint > 255) brint = 255;
129	  SPI_REG32(SPI_IO_CFG2) = brint << 8;
130	
131	  /* CR1: 使能 SPI */
132	
133	  SPI_REG32(SPI_IO_CR1) = SPI_CR1_SPE;
134	
135	  printf("[SPI] Init done, base=0x%lx, sclk=%lu Hz\n",
136	         (unsigned long)SPI_BASE, (unsigned long)SPI_CLOCK_HZ);
137	  return 0;
138	}
139	
140	/****************************************************************************
141	 * Name: spi_xfer_byte
142	 *
143	 * Description:
144	 *   单字节 SPI 传输（全双工）。
145	 *
146	 * Input Parameters:
147	 *   tx - 发送字节
148	 *   rx - 接收字节指针（可为 NULL）
149	 *
150	 * Returned Value:
151	 *   0 on success, -1 on timeout.
152	 ****************************************************************************/
153	
154	int spi_xfer_byte(uint8_t tx, uint8_t *rx)
155	{
156	  uint32_t val;
157	  uint32_t sr1;
158	  uint32_t i;
159	
160	  /* 1. 使能 SPI */
161	
162	  val = SPI_REG32(SPI_IO_CR1);
163	  val |= SPI_CR1_SPE;
164	  SPI_REG32(SPI_IO_CR1) = val;
165	
166	  /* 2. 终止待处理传输 */
167	
168	  val = SPI_REG32(SPI_IO_CR1);
169	  val &= ~(SPI_CR1_CSTART | SPI_CR1_AUTOSUS);
170	  SPI_REG32(SPI_IO_CR1) = val;
171	
172	  /* 3. 清除状态标志 */
173	
174	  SPI_REG32(SPI_IO_SR1) = SPI_SR1_W1C_FLAGS;
175	
176	  /* 4. TSIZE = 0（单帧） */
177	
178	  SPI_REG32(SPI_IO_CR3) = 0;
179	
180	  /* 5. 等待 TX FIFO 可写 */
181	
182	  for (i = 0; i < SPI_WAIT_TIMEOUT_US; i++)
183	    {
184	      sr1 = SPI_REG32(SPI_IO_SR1);
185	      if (sr1 & SPI_SR1_TXA) break;
186	      up_udelay(1);
187	    }
188	
189	  if (i >= SPI_WAIT_TIMEOUT_US) goto abort;
190	
191	  /* 6. 写入 TX 字节（⚠️ 8 位写入！） */
192	
193	  SPI_REG8(SPI_IO_DR) = tx;
194	
195	  /* 7. 启动传输（只置 CSTART，不置 AUTOSUS） */
196	
197	  val = SPI_REG32(SPI_IO_CR1);
198	  val |= SPI_CR1_CSTART;
199	  SPI_REG32(SPI_IO_CR1) = val;
200	
201	  /* 8. 等待 EOT（传输结束标志） */
202	
203	  for (i = 0; i < SPI_WAIT_TIMEOUT_US; i++)
204	    {
205	      sr1 = SPI_REG32(SPI_IO_SR1);
206	      if (sr1 & SPI_SR1_EOT) break;
207	      up_udelay(1);
208	    }
209	
210	  if (i >= SPI_WAIT_TIMEOUT_US) goto abort;
211	
212	  /* 9. 清除 EOT */
213	
214	  SPI_REG32(SPI_IO_SR1) = SPI_SR1_EOT;
215	
216	  /* 10. 等待 RX FIFO 有数据 */
217	
218	  for (i = 0; i < SPI_WAIT_TIMEOUT_US; i++)
219	    {
220	      sr1 = SPI_REG32(SPI_IO_SR1);
221	      if (sr1 & SPI_SR1_RXA) break;
222	      up_udelay(1);
223	    }
224	
225	  if (i >= SPI_WAIT_TIMEOUT_US) goto abort;
226	
227	  /* 11. 读取 RX 字节（⚠️ 8 位读取！） */
228	
229	  if (rx) *rx = SPI_REG8(SPI_IO_DR);
230	  else     (void)SPI_REG8(SPI_IO_DR);
231	
232	  return 0;
233	
234	abort:
235	  val = SPI_REG32(SPI_IO_CR1);
236	  val &= ~(SPI_CR1_CSTART | SPI_CR1_AUTOSUS);
237	  SPI_REG32(SPI_IO_CR1) = val;
238	  SPI_REG32(SPI_IO_CR4) = 0;
239	  SPI_REG32(SPI_IO_CR3) = 0;
240	  up_udelay(10);
241	  SPI_REG32(SPI_IO_SR1) = SPI_SR1_W1C_FLAGS;
242	  for (i = 0; i < 4; i++)
243	    {
244	      if (SPI_REG32(SPI_IO_SR1) & SPI_SR1_RXE) break;
245	      (void)SPI_REG8(SPI_IO_DR);
246	    }
247	
248	  ioctl(g_fd_cs, GPIOC_WRITE, 1);
249	  up_udelay(1);
250	  return -1;
251	}
252	
253	/****************************************************************************
254	 * Name: spi_cs_low / spi_cs_high
255	 *
256	 * Description:
257	 *   软件控制片选信号。
258	 ****************************************************************************/
259	
260	void spi_cs_low(void)
261	{
262	  ioctl(g_fd_cs, GPIOC_WRITE, 0);
263	  up_udelay(1);
264	}
265	
266	void spi_cs_high(void)
267	{
268	  ioctl(g_fd_cs, GPIOC_WRITE, 1);
269	  up_udelay(1);
270	}
271	
272	/****************************************************************************
273	 * Name: spi_deinit
274	 ****************************************************************************/
275	
276	void spi_deinit(void)
277	{
278	  if (g_fd_cs >= 0)
279	    {
280	      spi_cs_high();
281	      close(g_fd_cs);
282	      g_fd_cs = -1;
283	    }
284	}
